import type { VizChapter } from './types';

const CHAPTERS: VizChapter[] = [{"id":"tool-ch01","subj":"tooling","title":"Linux 基础：文件系统与权限","summary":"FHS 目录结构与各目录职责；「一切皆文件」与 inode、硬链接计数；权限位（rwx 与数字表示、umask、chmod/chown/chgrp）与特殊权限（setuid/setgid/sticky）；软链接 vs 硬链接的本质差异；文本…","concepts":[{"id":"tool-ch01/01-fhs-and-inode","file":"01-fhs-and-inode.md","title":"一切皆文件：inode、目录项与文件系统布局","kind":"stack","secs":[{"h":"一、先破除一个「日常直觉」","s":"日常我们用「文件」指三件不同的东西，混在一起就永远说不清硬链接：","c":{"lang":"text","code":"目录 /home/zyx 的数据块（概念示意）：\n┌─────────────┬────────────┐\n│ 名称        │ inode 编号 │\n├─────────────┼────────────┤\n│ .           │  131074    │   ← 指向自己（目录自身）\n│ ..          │  131073    │   ← 指向父目录\n│ report.txt  │  262145    │  ─┐\n│ notes.md    │  262146    │   │  两条记录可以指向同一个 inode\n│ report-old  │  262145    │  ─┘  → 这就是硬链接\n…"}},{"h":"二、inode 里到底有什么","s":"inode（index node）是文件系统为每个文件分配的一个固定大小的结构体。典型内容：","c":{"lang":"text","code":"struct inode {                       // 概念模型，非某具体实现\n    mode_t   i_mode;      // 文件类型（普通/目录/符号链接/设备/管道…）+ 12 位权限\n    nlink_t  i_nlink;     // ★ 硬链接计数：有多少条目录项指向我\n    uid_t    i_uid;       // 属主\n    gid_t    i_gid;       // 属组\n    off_t    i_size;      // 字节数\n    time_t   i_atime;     // 最近访问时间\n    time_t   i_mtime;     // 最近修改时间（内容）\n    time_t   i_ctime;     // 最近变更时间（inode 元数据，如权限/chown）\n…"}},{"h":"三、三条「反直觉」推论","s":"一旦接受「inode 是本体、名字只是目录里的一条记录」，下面三件事就不用背了。","c":{"lang":"bash","code":"ln report.txt backup.txt   # 目录里多一条记录，i_nlink: 1 → 2\nrm report.txt              # 目录里少一条记录，i_nlink: 2 → 1\ncat backup.txt             # 依然能读！数据块没动过"}},{"h":"四、FHS：为什么目录要这样分","s":"FHS（Filesystem Hierarchy Standard）不是随意约定，它编码了「什么该被备份、什么该被共享、什么可以重建」这三类信息：","c":{"lang":"bash","code":"ls -ld /bin                     # /bin -> usr/bin"}},{"h":"五、工程实践：三条硬规则","s":"1. 不要用 ls 的输出做逻辑判断。 文件名可以包含空格、换行、、-。要遍历用 find ... -print0 + xargs -0，或 glob 加引号。","c":null},{"h":"六、自测问题","s":"1. 一个文件 inode 显示 Links: 3，删掉其中一个名字后还剩几个名字？数据何时真正释放？","c":null}]},{"id":"tool-ch01/02-permissions","file":"02-permissions.md","title":"权限模型：rwx 的双重语义与三个特殊位","kind":"flow","secs":[{"h":"一、权限位的物理位置","s":"权限存在 inode 的 i_mode 字段里。i_mode 是 16 位，低 12 位是权限：","c":{"lang":"text","code":"i_mode（16 位）\n┌──┬──┬──┬───┬───┬───┬───┬───┬───┬───┬───┬───┐\n│  │  │  │ U │ U │ U │ G │ G │ G │ O │ O │ O │\n│  │  │  │ r │ w │ x │ r │ w │ x │ r │ w │ x │\n└──┴──┴──┴───┴───┴───┴───┴───┴───┴───┴───┴───┘\n  ↑  ↑  ↑   └User┘    └Group┘    └Other┘\n  │  │  └ sticky（1）\n  │  └ setgid（2）\n  └ setuid（4）        高 4 位是文件类型：S_IFREG / S_IFDIR / S_IFLNK ..."}},{"h":"二、核心难点：rwx 对目录的含义完全不同","s":"这是面试最高频的分水岭问题。对目录，三个位的语义是：","c":{"lang":"bash","code":"chmod 444 dir        # dr--r--r--\nls dir               # ✅ 成功！列出：a.txt b.txt\ncat dir/a.txt        # ❌ Permission denied"}},{"h":"三、umask：权限的\"默认值生成器\"","s":"新建文件的权限不取决于 open() 里写的 mode，而是：","c":{"lang":"text","code":"实际权限 = 请求权限 & ~umask"}},{"h":"四、三个特殊权限位","s":"它们占\"第四位八进制\"（如 4755、2755、1777）。ls -l 里显示为 s/t：","c":{"lang":"bash","code":"ls -l /usr/bin/passwd     # -rwsr-xr-x 1 root root ..."}},{"h":"五、权限的判定顺序（内核实际怎么判）","s":"","c":{"lang":"text","code":"进程要访问一个 inode：\n  1. 若 euid == 0（root）        → 直接放行（执行位例外：文件无任何 x 位时 root 也不能执行数据文件）\n  2. 若 euid == inode.i_uid      → 用「属主」三位判定\n  3. 否则若 egid（或附加组之一）== inode.i_gid → 用「属组」三位判定\n  4. 否则                        → 用「其他」三位判定\n  5. 任一步未通过 → 返回 EACCES（即 \"Permission denied\"）"}},{"h":"六、工程实践清单","s":"1. 脚本默认 umask 022，处理凭据目录用 077。不要依赖继承来的 umask。","c":null},{"h":"七、自测问题","s":"1. 目录权限为 d-wx--x---，属主能做什么？不能做什么？","c":null}]},{"id":"tool-ch01/03-hardlink-symlink","file":"03-hardlink-symlink.md","title":"硬链接与软链接：两种\"链接\"的本质差异","kind":"flow","secs":[{"h":"一、一句话结论","s":"","c":null},{"h":"二、硬链接：验证「共享 inode」","s":"两个观察点：inode 编号相同（同一本体）、Links 都是 2（i_nlink 存在 inode 里，因此共享）。","c":{"lang":"bash","code":"echo \"important data\" > report.txt\nln report.txt backup.txt        # 建硬链接（不是 cp！）\n\nls -li report.txt backup.txt\n# 262145 -rw-r--r-- 2 zyx zyx 15 ... report.txt\n# 262145 -rw-r--r-- 2 zyx zyx 15 ... backup.txt\n#  ↑ 同一个 inode 编号        ↑ 计数变成 2"}},{"h":"三、符号链接：验证「独立文件」","s":"排查与清理：","c":{"lang":"bash","code":"echo \"target content\" > real.txt\nln -s real.txt link.txt\nls -li real.txt link.txt\n# 262200 -rw-r--r-- 1 zyx zyx 15 ... real.txt     ← inode 262200\n# 262201 lrwxrwxrwx 1 zyx zyx  8 ... link.txt -> real.txt\n#  ↑ 不同编号！      ↑ 首字符 l              ↑ size = 路径字符串的字节数"}},{"h":"四、为什么会有这些限制：内核视角","s":"如果允许，就会出现目录树中的环：","c":{"lang":"text","code":"dir A 包含条目 \"up\" → dir B\ndir B 包含条目 \"down\" → dir A"}},{"h":"五、怎么判断「我手上这个是哪种链接」","s":"按可靠性排序：","c":{"lang":"bash","code":"ls -l f                    # 首字符：l → 软链接\nls -li a b                 # 比对 inode 编号：相同 → 硬链接\nstat -c '%i %h %F' a       # inode 编号 / 链接计数 / 文件类型（%F 直接写 \"symbolic link\"）\ntest -L f                  # 专门判断软链接（等价 -h）\nfind . -samefile a         # 找出所有指向同一 inode 的路径（硬链接全在此）\nreadlink f                 # 输出软链接的目标路径（硬链接返回非零退出码）"}},{"h":"六、工程实践","s":"1. 发布/部署用软链接做原子切换：先解压到 releases/20261007-1/，再 ln -sfn releases/20261007-1 current（-n 防止目标为目录时建到内部）。","c":null},{"h":"七、自测问题","s":"1. ln a b 与 cp a b 之后，ls -l 输出分别有何不同？du 统计会有何不同？","c":null}]},{"id":"tool-ch01/04-text-toolchain","file":"04-text-toolchain.md","title":"文本三剑客与 find：从管道哲学到工程实战","kind":"flow","secs":[{"h":"一、为什么是这三个工具：Unix 管道哲学","s":"它们的能力边界来自同一句设计格言：","c":{"lang":"bash","code":"# 真实需求：统计各状态码出现次数，按次数降序\ngrep -oE '\" [0-9]{3} ' access.log | awk '{print $1}' | sort | uniq -c | sort -rn\n#   ↑ 只提取匹配部分   ↑ 取字段  ↑ 排序   ↑ 去重计数 ↑ 按次数反序"}},{"h":"二、grep：行的筛选器","s":"","c":{"lang":"bash","code":"grep -E 'error|warn' app.log        # 分支\ngrep -P '\\d{4}-\\d{2}-\\d{2}' app.log # PCRE 的 \\d，ERE 里没有"}},{"h":"三、sed：流的编辑器","s":"sed 的循环是：读一行 → 放进模式空间 → 按脚本执行命令 → 自动打印 → 读下一行。","c":{"lang":"bash","code":"sed -n '5,10p' file            # 打印第 5~10 行\nsed -n '/BEGIN/,/END/p' file   # ★ 提取两个标记之间的块（神器）\nsed -n '2p;5p' file            # 多地址\nsed -n '$p' file               # 最后一行（$ = 尾行地址）"}},{"h":"四、awk：字段化的数据处理器","s":"awk '!seen[$0]++' 值得单独理解：seen[$0]++ 先返回旧值再自增，未见过时返回 0（假），! 取反为真 → 打印。这是用 awk 的求值顺序实现的\"首见即输出\"。","c":{"lang":"bash","code":"awk '{print $1, $3}' file                    # 默认按空白分隔\nawk -F: '{print $1, $3}' /etc/passwd          # 指定分隔符\nawk -F, '{print $2}' data.csv                 # CSV 第 2 列\nawk '{print $NF}' file                        # ★ 最后一列（不用数列数）\nawk '$3 > 100 {print $1, $3}' file            # 条件过滤"}},{"h":"五、find：文件系统的查询语言","s":"find 不是\"查找命令\"，而是对目录树的条件查询 + 动作执行引擎：","c":{"lang":"text","code":"find <路径> <条件表达式> <动作>"}},{"h":"六、组合成真实工具：四条经典管道","s":"","c":{"lang":"bash","code":"# ① 找出 5xx 最多的前 10 个 IP\nawk '$9 ~ /^5/ {print $1}' access.log | sort | uniq -c | sort -rn | head -10\n\n# ② 统计每个源文件的代码行数并排序\nfind src -name \"*.c\" -print0 | xargs -0 wc -l | sort -rn | head -20\n\n# ③ 找出占用空间最大的 10 个目录（排除 .git 与 node_modules）\ndu -sh */ 2>/dev/null | grep -vE '\\.git|node_modules' | sort -rh | head -10\n\n…"}},{"h":"七、自测问题","s":"1. grep -E '\\d' 能匹配到数字吗？为什么？正确写法是什么？","c":null}]}],"exams":[{"kind":"choice","q":"目录权限 rwx 的语义：删除文件看的是谁的权限","stem":"环境：目录 d 权限 drwxr-x---，属主 alice，属组 devs；其下文件 d/f.txt 权限 -rw-r-----，属主 alice，属组 devs。 - bob：既不是 alice，也不属于 devs - carol：属于 devs（但不是 alice） 下列判断正确的是？","opts":[{"k":"A","t":"alice 可以 ls d 列出目录中的文件名"},{"k":"B","t":"bob 可以 cd d 进入该目录"},{"k":"C","t":"carol 可以 cat d/f.txt 读到文件内容"},{"k":"D","t":"carol 可以 rm d/f.txt 删除该文件"}],"ans":"AC","why":"把「目录 rwx 的三重语义」「判定短路」与「删除看目录权限」三个考点合并成一道题。"},{"kind":"output","q":"由 umask 推断新建文件与目录的权限","stem":"在 umask 027 的环境下，新建的普通文件与新建的目录权限分别是多少？请给出八进制与符号两种表示，并说明为什么文件的上限是 666 而不是 777。","opts":[],"ans":"文件 640（-rw-r-----）；目录 750（drwxr-x---）","why":"umask 是权限的「默认值生成器」，必须能用位运算手算。"},{"kind":"fix_error","q":"找出批量删除脚本中的两处安全隐患","stem":"下面的脚本用来清理 /var/log 下 7 天前的日志，请指出两处会导致误删或崩溃的问题，并给出修正版： bash #!/bin/bash cd /var/log FILES=find . -name \".log\" -mtime +7 for f in $FILES; do rm -f $f done","opts":[],"ans":"问题一：$FILES 未加引号 + 命令替换按空白拆分 → 文件名含空格/换行时破坏；问题二：rm -f $f 未加引号且变量可能为空/以 - 开头；另有隐患三：没有任何干跑确认，直接删。","why":"词拆分与 globbing 是 shell 脚本里最高频的误删来源，必须能识别。"},{"kind":"coding","q":"统计文件中单词的出现频率（LeetCode 192）","stem":"给定一个文本文件 words.txt，每行可能包含多个以空白分隔的单词（小写字母），要求统计每个单词出现的次数，按频次降序输出，频次相同的按单词字典序升序输出，每行格式为「单词 空格 次数」。请用 Shell（grep/sed/awk/sort 管道）实现。","opts":[],"ans":"cat words.txt | tr -s ' ' '\\n' | sort | uniq -c | sort -k2,2 -k1,1nr | awk '{print $2, $1}'","why":"经典 Shell 管道题，考 uniq 的前置排序要求与多键排序。"},{"kind":"coding","q":"筛选合法电话号码（LeetCode 193）","stem":"给定 file.txt，每行一个候选字符串，要求用一行 Shell 命令输出所有符合「xxx-xxx-xxxx」或「(xxx) xxx-xxxx」格式的号码（x 为数字），且不改变原始行顺序。","opts":[],"ans":"grep -E '^([0-9]{3}-|\\([0-9]{3}\\) )[0-9]{3}-[0-9]{4}$' file.txt","why":"考 ERE 与 BRE 的差异、锚点成对使用、以及 \\d 的方言陷阱。"},{"kind":"coding","q":"输出文件的第十行（LeetCode 195）","stem":"给定一个文本文件 file.txt（行数保证 ≥10），用一行 Shell 命令输出文件的第十行。请给出至少两种实现，并说明各自的适用性与限制。","opts":[],"ans":"sed -n '10p' file.txt","why":"考 sed 的 -n 与 p 配对、awk 的 NR、以及 UUOC 反模式。"}],"works":[{"h":"chmod 777 当万能钥匙","d":"现象：权限报错就 chmod 777，问题\"消失\"了。根因：777 对目录意味着任何人都能删改其中任何文件（除非 sticky 位），对可执行/脚本文件意味着任何人都能替换它。若该目录在 web 根或 PATH 中，等于开放了任意代码执行入口。正确做法：先 id + stat 定位是哪个分组缺权限，把属组设对（chgrp + setg…"},{"h":"chmod -R 777 递归放开上传目录","d":"现象：图片上传失败，于是对 upload 目录递归 777。根因：-R 会把执行位加到所有文件上（包括上传的 .php、.jsp），配合 web 服务器解析 = 直接 RCE。历史上大量 webshell 事件源于此。正确做法：chown -R www-data:www-data upload/ + chmod 755（目录）/ 64…"},{"h":"只看 rwx 不看属主/属组，误判 Permission denied","d":"现象：文件权限明明是 777 却仍报拒绝访问。根因：权限判定是短路的 —— 命中属主分支时就用属主三位，不会再去尝试属组/其他位。若文件属主位是 000、你恰好是属主，即使其他位是 777 也会被拒。另一个常见变体：你不在文件属组、附加组也没生效（需重新登录才刷新组）。正确做法：排查三步 id（我是谁/在哪些组）→ stat file…"},{"h":"把 rm 理解为\"彻底删除数据\"","d":"现象：误删后尝试恢复，或惊讶于 du 与 df 不一致。根因：rm 只是删除目录项并把 i_nlink 减一；i_nlink == 0 且无进程打开时才真正释放数据块。正确认知：① 有进程持有 fd 时数据仍可从 /proc/<pid>/fd/ 拷回（真实救援手段）；② 排查 df 满但 du 小：lsof +L1 找\"已删仍被占用\"…"},{"h":"以为符号链接的权限会生效","d":"现象：chmod 400 link 想限制访问。根因：符号链接自己的权限恒为 lrwxrwxrwx 且不参与判定，权限检查作用在目标上；chmod link 实际改的是目标文件（chmod -h 在多数系统不支持）。正确做法：要控制访问应改目标文件的权限，或把链接放进一个权限受控的目录（利用目录的 x 位控制穿越）。"},{"h":"sed -i 原地修改把软链接变成普通文件","d":"现象：改完配置文件后，原本指向 sites-available/ 的符号链接变成了独立文件，配置管理关系悄悄断裂。根因：sed -i 的实现是\"写临时文件 + rename\"，rename 会替换掉链接本身。正确做法：① 用 sed -i.bak 至少留备份；② 对软链接先 readlink -f 拿到真实路径再改；③ 用配置管理工具…"},{"h":"grep -E '\\d' 匹配不到数字（却可能匹配到字母 d）","d":"现象：写 grep -E '\\d+' 想抓数字，结果为空或抓到了含字母 d 的内容。根因：\\d 是 PCRE 专有，ERE 里未定义；GNU grep 在 ERE 下可能把 \\d 退化为字面量 d，BSD grep 行为又不同 —— 静默错误最难查。正确做法：grep -P '\\d+'（GNU 专用）或统一写 [0-9]+（POSIX…"},{"h":"sed -n '2p' 忘写 -n，输出全部行","d":"现象：只想看第 2 行，结果打印了整个文件（且第 2 行出现两次）。根因：sed 的循环默认自动打印每行，p 命令是额外再打印一次。正确做法：只要\"选择性输出\"就必须 -n；混用时的记忆法是「-n 与 p 配对出现」。"}],"asks":[{"q":"软链接和硬链接的本质区别是什么？请从 inode 的角度解释，并说明为什么内核禁止对目录建硬链接、却允许软链接指向目录。","a":"本质：一个是「多一个名字」，另一个是「一个存着路径的小文件」。 硬链接：在目录的数据块里再增加一条 名称 → inode 编号 的记录。两个名字指向同一个 inode（stat 显示相同 Inode 编号），i_nlink 计数加一。它不占额外空间（只有目录项那几个字节），因为数据块与元数据都是共享的。 软链接：创建一个新的 inode（类型 S_IFLNK），它的数据块内容就是目标路径字符串。所…","fu":["ls -li a b 如何判断 a 与 b 是不是硬链接？find 里哪个选项能列出同一 inode 的所有名字？（fi…","为什么 find . -xtype l 比 find . -type l 更适合找坏链接？（-xtype 解引用后判断类…"],"tag":"字节跳动/阿里云"},{"q":"rm 一个文件后，为什么数据有可能还能找回来？df 显示磁盘满但 du 统计正常，如何排查？","a":"核心：rm 删的不是数据，是「名字」。 rm file 的实际动作是 unlink()：从目录数据块中删除那条 名称 → inode 记录，并把 inode 的 i_nlink 减一。真正释放 inode 与数据块的条件是： > i_nlink == 0 且没有任何进程持有该文件的打开文件描述符 场景一：进程仍在写入/读取，数据可救 日志进程把文件 rm 掉后仍在往里写（它持有 fd，inode…","fu":["为什么生产环境「清理日志」推荐 > file（截断）或 logrotate，而不是 rm + 重启服务？","lsof +L1 中的 +L1 是什么含义？"],"tag":"阿里云/腾讯"},{"q":"setuid 位是怎么工作的？为什么 passwd 需要它？它带来什么安全风险，如何审计？","a":"机制：执行时改变进程的有效 UID（euid）。 普通文件带 setuid 位（ls -l 显示 -rwsr-xr-x 中的 s）时，任何用户执行它，进程的 euid 会被设为该文件的属主 UID（而不是执行者的 UID）。于是程序内部就以属主身份运行。 为什么 passwd 必须这样： - 密码哈希存在 /etc/shadow，其权限是 ---------- 1 root shadow（普通用户…","fu":["setuid 对目录有什么效果？为什么现代系统基本不用它？","chmod u+s 与 chmod 4755 是否等价？ls -l 中 s 与 S 的区别是什么？（S = setuid…"],"tag":"奇安信/腾讯"},{"q":"为什么不建议用 ls 或 ps 的输出来做逻辑判断？给出安全的替代方案。","a":"根因：这些命令的输出是「给人看的」，不是「给机器读的」，没有稳定的机器可解析契约。 （1）ls 的问题 - 文件名可含空格与换行。POSIX 文件名允许除 / 与 NUL 之外的任意字节，所以 ls 的输出无法用空白可靠切分。 - 文件名可含 -，被下游命令当成选项（rm -rf 灾难的来源）。 - ls 会做列对齐、颜色转义、引号转义，列宽随终端宽度变化 → 同一份数据在不同终端下输出不同。 -…","fu":["为什么 NUL（\\0）是唯一安全的文件名分隔符？（文件名不能含 NUL，这是内核层面的限制）","while IFS= read -r -d '' f 里 IFS= 与 -r 分别解决什么问题？（不剥除前导空白、不解释…"],"tag":"美团/字节跳动"}]},{"id":"tool-ch02","subj":"tooling","title":"Linux 进程、管道与 Shell 脚本","summary":"进程查看与信号（ps/top/kill/SIGTERM 与 SIGKILL 的区别）；前台后台、nohup 与守护进程；管道与重定向（>/>>/2>&1/tee/xargs）；环境变量与 PATH 查找；Shell 脚本（变量、条件、循环…","concepts":[{"id":"tool-ch02/01-process-model","file":"01-process-model.md","title":"进程模型：fork/exec 与进程树、状态机","kind":"timeline","secs":[{"h":"一、进程是什么：fork/exec 语义与进程树","s":"进程的教科书定义是「资源分配的基本单位、程序的一次执行实例」。但工程上更有用的是视角转换：","c":{"lang":"text","code":"进程树（概念示意，PID 为示意值）\nsystemd(1)\n  └─ bash(1000)               ← 交互 shell\n       ├─ fork→ ls(1001)      ← bash fork 后 exec 成 ls\n       ├─ fork→ grep(1002)    ← 管道右侧：bash 先建 pipe 再 fork 两端\n       └─ fork→ bash(1003)    ← 执行脚本：fork 出的子 bash，退出不回传变量"}},{"h":"二、进程状态机：R / S / D / Z / T 与僵尸、孤儿","s":"Linux 进程在 task_struct 里有一个 state 字段，用户态常见五态（内核态更细，含就绪/运行合并为 R）：","c":{"lang":"text","code":"状态转移（简化）\n    fork                      收到 SIGSTOP / TSTP\n  ┌──────┐                      ┌──────────┐\n  │  R   │ 运行/就绪（CPU 或 runqueue） ◄──┐  │   T   │ 停止（作业控制）\n  └──┬───┘                              ├──┘──────────┘\n     │ 等待事件（IO/锁/信号量）          │  SIGCONT\n     ▼                                  │\n  ┌──────┐  事件到达              ┌─────┴────┐\n  │  S   │ 可中断睡眠（可被信号唤醒）       │\n…"}}]},{"id":"tool-ch02/02-signals","file":"02-signals.md","title":"信号：递送、默认行为与不可捕获信号","kind":"flow","secs":[{"h":"一、信号的递送模型与「默认行为」","s":"信号是内核向进程发送的软中断：不携带复杂数据，只表达「某类事件发生」。每个信号有一个默认处置（disposition）：","c":{"lang":"text","code":"信号递送（简化）\n  事件(内核/其他进程) ──► 置位 pending 位图 ──► 内核在「从内核态返回用户态」的时机检查\n    │                                                  │\n    │ 若被阻塞(blocked) ──► 保持 pending，解阻塞后再递送\n    ▼\n  按 disposition 处理：handler / 默认(Term|Core|Ign|Stop|Cont)"}},{"h":"二、四个核心信号：SIGTERM / SIGKILL / SIGINT / SIGHUP","s":"面试与排障最高频的四个：","c":{"lang":"text","code":"典型递送场景\nCtrl-C         ──► SIGINT  ──► 前台进程组（默认 Term）\nkill <pid>     ──► SIGTERM ──► 目标进程（可优雅退出）\nkill -9 <pid>  ──► SIGKILL  ──► 内核直接回收（无清理）\n终端关闭        ──► SIGHUP   ──► 会话进程组（默认 Term；daemon 复用于 reload）"}}]},{"id":"tool-ch02/03-pipe-redirection","file":"03-pipe-redirection.md","title":"管道、重定向与文件描述符表","kind":"compare","secs":[{"h":"一、管道与重定向的本质：fd 表的复制与重定向","s":"一切从「进程的 fd 表」出发。fd 表是内核里「小整数 → 打开文件描述」（file description）的数组；0=stdin、1=stdout、2=stderr。","c":{"lang":"text","code":"ls | wc -l 的 fd 表（简化）\n  ls : fd0=终端  fd1 ──┐      wc : fd0 ──┐  fd1=终端\n                       │pipe 写端        │pipe 读端\n  （ls 的 stdout 重定向到 pipe 写端，wc 的 stdin 重定向到 pipe 读端）"}},{"h":"二、xargs/find -exec/tee：批量与组合的工程取舍","s":"find 与 xargs 都能「找到文件并对每个执行命令」，差异在进程创建次数与分隔符安全性：","c":null}]},{"id":"tool-ch02/04-shell-scripting","file":"04-shell-scripting.md","title":"Shell 脚本工程化：变量、退出码与守护","kind":"flow","secs":[{"h":"一、变量、条件、循环、$? 与 set -euo pipefail","s":"Shell 是解释执行的命令语言，不是通用编程语言。几个最容易翻车的点：","c":{"lang":"text","code":"健壮脚本头（行业底线）\n#!/usr/bin/env bash\nset -euo pipefail        # e:出错即停  u:未定义变量即错  o pipefail:管道任一段失败则失败\nIFS=$'\\n\\t'            # 收紧词拆分分隔符（仅换行/tab）"}},{"h":"二、环境变量/PATH、cron、systemd 与 SSH 密钥登录","s":"脚本要「上线」就离不开这三组工程原语：","c":{"lang":"text","code":"SSH 公钥登录挑战-响应（简化）\n  Client                               Server\n    │                                    │ 持有 authorized_keys 里的公钥\n    │  ←── 发送随机 challenge ────       │\n    │  用私钥对 challenge 签名           │\n    │  ──── 发送签名 ──►                 │ 用公钥验证签名\n    │                                    │ 验证通过 → 允许登录（私钥从未离开客户端）"}}]},{"id":"tool-ch02/05-linux-process-snippets","file":"05-linux-process-snippets.md","title":"Linux 进程与管道代码速查：凯喵的七段可直接用的片段","kind":"flow","secs":[{"h":"一、查看进程树与真实父进程","s":"ps 的默认输出看不出层级，--forest 才能看清谁是谁的孩子。","c":{"lang":"bash","code":"ps -eo pid,ppid,stat,etime,rss,cmd --forest | head -40"}},{"h":"二、按端口找进程","s":"排障时最常见的问题：某个端口被占用了，不知道是谁。","c":{"lang":"bash","code":"ss -lntp | grep ':8080'\n# 或\nlsof -i TCP:8080 -sTCP:LISTEN"}},{"h":"三、信号的正确发送方式","s":"顺序永远是「先 TERM，等几秒，再看情况 KILL」。直接 KILL 会跳过所有清理逻辑，可能留下锁文件、临时文件、半写的数据。","c":{"lang":"bash","code":"kill -TERM <pid>      # 请它优雅退出（可被捕获）\nkill -INT <pid>       # 相当于 Ctrl-C\nkill -KILL <pid>      # 强杀，不可捕获、不给清理机会\nkill -HUP <pid>       # 常用于让守护进程重读配置"}},{"h":"四、管道的退出码陷阱","s":"默认情况下 a | b 的退出码是 b 的退出码，a 失败了也看不出来。pipefail 会取整条管道中最先失败的那个，这是脚本里必须开的一项。","c":{"lang":"bash","code":"set -o pipefail     # 让管道返回最右侧失败命令的退出码"}},{"h":"五、进程替换避免临时文件","s":"有些命令只接受文件名不接受 stdin，进程替换能免掉临时文件。","c":{"lang":"bash","code":"diff <(sort a.txt) <(sort b.txt)\ncomm -12 <(sort a.txt) <(sort b.txt)      # 求交集"}},{"h":"六、按条件批量处理文件","s":"三个细节：-print0 配 xargs -0 处理含空格和换行的文件名；-r 表示没有输入时不执行（避免 gzip 因为没参数而报错）；-n 20 每批 20 个，避免命令行过长。","c":{"lang":"bash","code":"find . -name '*.log' -size +100M -mtime +7 -print0 \\\n  | xargs -0 -r -n 20 gzip -9"}},{"h":"七、后台任务与作业控制","s":"区别：& 只是放后台，shell 退出时可能收到 SIGHUP；nohup 让进程忽略 SIGHUP；disown 把作业从 shell 的作业表里移除，之后 shell 退出不再通知它。","c":{"lang":"bash","code":"cmd > out.log 2>&1 &\njobs -l\ndisown -h %1\nnohup cmd > out.log 2>&1 &"}},{"h":"收尾","s":"这七段命令覆盖了 Linux 日常排障与运维的高频场景：看进程树、找端口、发信号、处理管道退出码、进程替换、批量处理、后台任务。凯喵的体会是，这些命令的价值不在于「知道有这个命令」，而在于知道每个选项对应的具体行为——比如 kill -…","c":null}]}],"exams":[{"kind":"choice","q":"僵尸进程与孤儿进程的成因与回收","stem":"下列说法正确的是？（多选） 请选择并说明。","opts":[{"k":"A","t":"子进程先于父进程退出、父进程未调用 wait()，子进程会变成僵尸（Z）状态，残留 task_struct 占一个 pi…"},{"k":"B","t":"僵尸进程可以通过 kill -9 杀掉，因为它还「活着」"},{"k":"C","t":"父进程先于子进程退出时，子进程会被 init（pid 1） 或最近的 subreaper 收养，照常运行，不是「丢失」"},{"k":"D","t":"孤儿进程无法被回收，会一直泄漏资源"}],"ans":"AC","why":"考僵尸/孤儿的发生条件与回收责任，是 408 与 SRE 面试高频。"},{"kind":"choice","q":"SIGTERM 与 SIGKILL 的语义差异","stem":"运维需要停止一个正在运行的服务进程。关于 SIGTERM(15) 与 SIGKILL(9)，下列说法正确的是？ 请选择并说明。","opts":[{"k":"A","t":"kill PID（不带参数）默认发送 SIGKILL，立即强制杀掉进程"},{"k":"B","t":"SIGTERM 可被进程捕获，进程可借机 flush 缓冲区、关连接、删 pidfile 后优雅退出"},{"k":"C","t":"SIGKILL 不可被捕获、阻塞或忽略，内核直接回收进程，跳过所有清理逻辑"},{"k":"D","t":"数据库正在写 WAL 时，应优先用 SIGKILL 以保证「立刻停」"}],"ans":"BC","why":"考信号默认行为与「为什么不该把 SIGKILL 当首选」。"},{"kind":"output","q":"推断 2>&1 顺序对 fd 表的影响","stem":"shell 要把「stdout 与 stderr 都写进 log.txt」。下面两条命令，哪一条能正确做到？请分别说明 fd 1、fd 2 最终指向的目标。 cmd1: 2>&1 > log.txt cmd2: > log.txt 2>&1 给出 cmd1 与 cmd2 各自的结果（stderr 最终去了哪里）。","opts":[],"ans":"cmd2 正确；cmd1 只有 stdout 进 log.txt，stderr 仍打到终端","why":"考 fd 表视角下重定向的顺序敏感性，output 题经典陷阱。"},{"kind":"coding","q":"用 Python 模拟 fork 后父子进程的内存独立性","stem":"UNIX 里 fork() 复制父进程地址空间、exec() 替换映像。请用一段可直接执行的 Python模拟： 「父进程持有一个字典变量；fork（此处用复制而非真实 fork 模拟写时复制）出子进程的独立副本；子进程修改自己的副本，父进程的副本不受影响」。 要求：打印父、子各自的变量值，并断言二者相互独立。","opts":[],"ans":"见 reference_code（父 x=10、子 x=99，互不影响）","why":"用可执行 Python 落地 fork/exec 的 COW 语义，呼应 concept/01。"},{"kind":"coding","q":"统计单词出现频率（LeetCode 192）","stem":"给定一个文本文件，每行可能含多个以空白分隔的单词（小写字母），统计每个单词出现次数，按频次降序输出，频次相同按单词字典序升序输出，每行「单词 空格 次数」。请用 Shell 管道实现。 （题面详见 external_url，本库只存元数据与链接，不搬运题面正文。）","opts":[],"ans":"cat file.txt | tr -s ' ' '\\n' | sort | uniq -c | sort -k2,2 -k1,1nr | awk '{print $2, $1}'","why":"经典 Shell 管道题，考 uniq 的前置排序与多键排序。"},{"kind":"coding","q":"筛选合法电话号码（LeetCode 193）","stem":"给定文件，每行一个候选字符串，用一行 Shell输出符合「xxx-xxx-xxxx」或「(xxx) xxx-xxxx」格式的号码（x 为数字），且保持原行顺序。 （题面详见 external_url，本库只存元数据与链接。）","opts":[],"ans":"grep -E '^([0-9]{3}-|\\([0-9]{3}\\) )[0-9]{3}-[0-9]{4}$' file.txt","why":"考 ERE 与 BRE 差异、锚点成对、及 \\d 方言陷阱。"},{"kind":"coding","q":"转置文件（LeetCode 194）","stem":"给定一个文本文件，每行长度相同、由空格分隔成若干列，要求把行转成列（转置）输出，列之间以空格分隔。 （题面详见 external_url，本库只存元数据与链接。）","opts":[],"ans":"awk '{ for (i=1; i<=NF; i++) a[i]=a[i] (NR==1?\"\":\" \") $i } END { for (i=1; i in a; i++) print a[i] }' file.txt","why":"考 awk 关联数组做矩阵转置，是 Shell 里少见的二维处理。"},{"kind":"coding","q":"输出文件的第十行（LeetCode 195）","stem":"给定文本文件（行数 ≥10），用一行 Shell输出第十行。 （题面详见 external_url，本库只存元数据与链接。）","opts":[],"ans":"sed -n '10p' file.txt","why":"考 sed 的 -n 与 p 配对、awk 的 NR。"}],"works":[{"h":"把 kill PID 当成 SIGKILL","d":"现象：进程没退，你以为 kill 失效了又连发几次。根因：kill 默认发 SIGTERM(15)，进程可以选择忽略或延迟处理（比如正在刷盘）。正确做法：先 kill PID（SIGTERM）给优雅退出机会；超时仍未退出再 kill -9 PID（SIGKILL）。把 SIGKILL 当首选会跳过清理逻辑，造成数据损坏或临时文件泄漏。"},{"h":"用 SIGKILL 杀正在写数据的进程","d":"现象：数据库/日志进程被 kill -9 后文件损坏、索引不一致。根因：SIGKILL 是不可捕获、不可阻塞、不可忽略的，进程收到即被内核直接回收，没有机会执行 atexit、flush、释放锁。正确做法：优先 SIGTERM；只有确认进程已卡死（D 状态超时、死锁）才用 SIGKILL，且之后必须做一致性恢复（如 DB 的 cras…"},{"h":"僵尸进程用 kill -9 杀不掉","d":"现象：ps 里一堆 <defunct>，kill -9 毫无反应。根因：僵尸已经死了，只是父进程还没 wait() 回收它的退出状态，残留一个 task_struct（占 pid 槽）。SIGKILL 对尸体无效。正确做法：杀掉它的父进程（或让父进程正确调用 wait/waitpid），父进程死后僵尸被 init/subreaper…"},{"h":"误以为孤儿进程「丢失」了","d":"现象：父进程先退出，子进程还在跑，你担心它变成野进程。根因：父进程退出后，子进程会被 init（pid 1）或最近的 subreaper 收养，ppid 变成 1，调度与回收都正常。正确做法：这不是 bug；若你希望子进程随父退出而退出，应当显式处理 SIGHUP/SIGTERM 或 prctl(PR_SET_PDEATHSIG)。"},{"h":"2>&1 > file 把 stderr 也写进了 file","d":"现象：想「stderr 和 stdout 都进文件」，但 stderr 还是打到了终端。根因：重定向是按顺序、对 fd 表即时生效的。2>&1 先把 fd 2 复制到「fd 1 当前指向的目标」（此时还是终端），随后 > file 才把 fd 1 指向 file——fd 2 仍指向终端。正确做法：写成 > file 2>&1（先把 f…"},{"h":"echo $? 取到的是管道里最后一个命令的退出码","d":"现象：false | true; echo $? 打印 0，你以为「整条管道成功了」。根因：$? 只保存最近一条命令的退出码；管道整体退出码默认是最后一个命令的。正确做法：需要「任一失败即失败」用 set -o pipefail（此时 $? 取管道中第一个非零退出码）；需要每个命令的码用 ${PIPESTATUS[@]}。"},{"h":"以为 set -e 能拦住管道里的失败","d":"现象：脚本里 curl ... | grep ok 失败（curl 500）但脚本继续跑、后续全错。根因：set -e 默认只看整条管道最后一个命令的退出码，中间的失败被忽略。正确做法：必须配 set -o pipefail，或显式检查 ${PIPESTATUS[0]}；推荐脚本开头永远 set -euo pipefail。"},{"h":"set -e 下条件里的命令失败却不退出","d":"现象：if mycmd; then ...; fi 里 mycmd 失败，脚本没退出，你以为 set -e 失效了。根因：这是 set -e 的标准例外——if/while/until 的条件表达式、&&/|| 链中非末位的命令，其失败是「被预期用来控制流程」的，不触发退出。正确做法：真正需要「失败即停」的逻辑不要塞进条件；或在条件后…"}],"asks":[{"q":"僵尸进程和孤儿进程有什么区别？分别如何产生、如何回收？","a":"僵尸（Zombie）：子进程 exit() 后，内核释放其地址空间与 fd，但保留 task_struct 与退出码，直到父进程 wait()/waitpid() 取走才删除。产生条件：子先退出、父未 wait。它不占内存/CPU，只占一个 pid 槽；kill -9 无效（已死）。回收：让父进程正确 wait，或杀掉父进程使其被 init 收养并立即回收。 孤儿（Orphan）：父进程先于子退出…","fu":["kill -9 为什么杀不死僵尸？（尸体已终止，信号只能发给存活进程）","容器里僵尸堆积的根因与解法（tini/dumb-init 当 PID 1）"],"tag":"字节跳动/阿里云"},{"q":"SIGTERM 和 SIGKILL 有什么区别？为什么 SIGKILL 不能被捕获？","a":"语义差异： - SIGTERM(15)：kill 默认发送，默认行为 Term，但可被捕获/忽略——进程可注册 handler 优雅退出（flush、关连接、删 pidfile）。是「礼貌的请求」。 - SIGKILL(9)：立即终止，不可捕获、不可阻塞、不可忽略，内核直接回收进程，跳过所有清理。 为什么 SIGKILL 不可捕获：它是操作系统的最终控制权——内核/管理员必须能终止任何失控、死锁…","fu":["SIGINT 和 SIGTERM 的区别？（Ctrl-C 发给前台进程组 vs 管理员终止请求）","D 状态进程为什么连 SIGKILL 都杀不掉？（等内核关键区 IO 返回）"],"tag":"阿里云/腾讯"},{"q":"管道和重定向的本质是什么？请解释 2>&1 的 fd 机制。","a":"本质都是对 fd 表的操作：fd 表是「小整数 → 打开文件描述」的数组，0=stdin/1=stdout/2=stderr。 - 重定向 > file：open 新 fd 后 dup2(new, 1)，让 fd 1 指向新 file description； - 管道 a | b：内核建一对 pipe fd（读端 r、写端 w，共享内存环形缓冲），a 的 fd 1 dup2 到 w、b 的 fd…","fu":["a | b 时 b 提前退出，a 会怎样？（写端收 SIGPIPE 终止 / write 得 EPIPE）","为什么 cat file | grep x > file 会清空 file？（> 在管道建立前已 truncate）"],"tag":"美团/字节跳动"},{"q":"set -euo pipefail 各自解决什么问题？为什么光 set -e 不够？","a":"set -e：任一命令返回非零且未被显式测试时，脚本立即退出。防「错误被静默忽略后后续全错」。 - set -u：引用未定义变量即报错退出，防 rm -rf \"$DIR/\" 中 DIR 为空退化成 rm -rf /。 - set -o pipefail：管道整体退出码取第一个非零段而非末段，使 curl ... | grep ok 中 curl 失败也能被感知。 为什么光 set -e 不够： 1…","fu":["set -e 下 if cmd; then 失败为什么不退出？（条件里的命令失败属预期）","echo $? 取到的是管道哪一段的退出码？（默认末段；pipefail 取首失败）"],"tag":"腾讯/阿里云"}]},{"id":"tool-ch03","subj":"tooling","title":"Git 核心：对象模型与分支","summary":"三种对象（blob/tree/commit）与内容寻址（SHA-1）；工作区/暂存区/版本库三态与三个 HEAD 引用；commit 是快照而非差异；分支只是指向 commit 的指针与 git switch；detached HEAD 的…","concepts":[{"id":"tool-ch03/01-object-model","file":"01-object-model.md","title":"对象模型：blob/tree/commit 与内容寻址存储","kind":"stack","secs":[{"h":"第1节 一、三类核心对象（blob/tree/commit）与内容寻址（CAS）","s":"Git 内核本质是一个内容寻址的文件系统（content-addressable storage）：所有数据都以「对象」形式存入 .git/objects，用其内容的 SHA-1 作为唯一键（文件名即哈希）。对象分四类——blob（文件…","c":null},{"h":"第2节 二、tree 与 commit 的结构：快照而非差异","s":"一个 commit 对象记录：指向顶层 tree 的指针、零或多个 parent（首提交无 parent，合并提交 ≥2 个）、author/committer 与时间、提交说明。一个 tree 对象记录该目录下每条目：文件模式（如 1…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"import os, subprocess, tempfile, hashlib, pathlib\n\nGIT_ENV = dict(os.environ)\nfor _k, _v in [(\"GIT_AUTHOR_NAME\", \"dev\"), (\"GIT_AUTHOR_EMAIL\", \"dev@example.com\"),\n               (\"GIT_AUTHOR_DATE\", \"2026-01-01T00:00:00+00:00\"),\n               (\"GIT_COMMITTER_NAME\", \"dev\"), (\"GIT_COMMITTER_EMAIL\", \"dev@example.com\"),\n               (\"GIT_COMMITTER_DATE\", \"2026-01-01T00:00:00+00:00\")]:\n    GIT_ENV[_k] = _v\n\n…"}}]},{"id":"tool-ch03/02-three-areas","file":"02-three-areas.md","title":"三区模型与分支指针：工作区/暂存区/版本库","kind":"flow","secs":[{"h":"第1节 一、工作区 / 暂存区 / 版本库（三区模型）","s":"Git 把文件状态分散在三个区域：工作区（working tree）是你直接编辑的目录；暂存区（index / stage）是「下一次 commit 的候选清单」，本质是待序列化成 tree 的草稿；版本库（repository）= 对…","c":null},{"h":"第2节 二、分支是指向 commit 的指针；HEAD 是「当前位置」","s":"在 Git 里分支只是 .git/refs/heads/<name> 里存的一行 commit SHA（41 字节：40 位十六进制 + 换行）。HEAD 是「当前所在位置」的符号引用：正常时指向某个分支（ref: refs/heads…","c":null}]},{"id":"tool-ch03/03-branch-merge","file":"03-branch-merge.md","title":"分支合并：快进、三方合并与冲突","kind":"compare","secs":[{"h":"第1节 一、快进合并 vs 三方合并（非快进）","s":"当「目标分支的顶端是源分支顶端的祖先」时，git merge 默认快进（fast-forward）：仅把目标分支指针移到源顶端，不产生新提交。当两边各自有新提交（分叉）时，必须做三方合并（three-way merge）：以共同祖先（m…","c":null},{"h":"第2节 二、冲突的产生与解决；merge-base 的角色","s":"冲突发生在：同一文件的同一区域，在 ours 与 theirs 相对 base 都被修改、且修改结果不同 时。Git 用 <<<<<<< / ======= / >>>>>>> 标记冲突区。git merge-base A B 给出最近…","c":null}]},{"id":"tool-ch03/04-reset-checkout-reflog","file":"04-reset-checkout-reflog.md","title":"reset/checkout/reflog 与标签：安全回退与救援","kind":"compare","secs":[{"h":"第1节 一、reset 三模式 + checkout/restore/revert 的区别","s":"git reset 移动 HEAD（并可顺带重置 index、工作树）；git checkout/git switch 切换分支或恢复文件；git restore 是更聚焦的文件级恢复（可指定 source 与 destination）…","c":null},{"h":"第2节 二、detached HEAD、reflog 救援与 tag/stash/cherr…","s":"git checkout <commit-sha> 会进入 detached HEAD：HEAD 直接存一个 commit SHA 而非分支引用。此时新提交「不属于任何分支」，切走后若未被引用似乎「丢失」——但 reflog（.git/…","c":null}]},{"id":"tool-ch03/05-git-objects-practical-recipes","file":"05-git-objects-practical-recipes.md","title":"Git 对象模型与分支实战手记：凯喵用 reflog 救回一次误删分支的十二个现场","kind":"flow","secs":[{"h":"开场：Git 只存四种对象，其余都是视图","s":"Git 的底层只有四种对象，全部存在 .git/objects 里，用内容的 SHA-1 命名：","c":{"lang":"text","code":"blob   文件内容（不含文件名）\ntree   目录（记录「文件名 → blob/tree 的映射」）\ncommit 一次提交（指向一个 tree + 父 commit + 作者 + 消息）\ntag    附注标签（指向某个 commit）"}},{"h":"收尾：凯喵的 Git 急救五招","s":"出事时按顺序想这五件事：","c":null}]}],"exams":[{"kind":"choice","q":"Git 与 SVN 的核心差异","stem":"关于 Git 与 SVN 的核心差异，下列说法正确的是？ 请选择并说明。","opts":[{"k":"A","t":"SVN 是分布式版本控制，每个开发者都有完整仓库；Git 是集中式"},{"k":"B","t":"Git 存储的是文件快照（snapshot）并以内容寻址（SHA-1）组织对象，SVN 主要存储文件差异（delta）"},{"k":"C","t":"Git 的「分支」只是一个指向 commit 的轻量指针（约 41 字节），SVN 的分支是目录拷贝，开销大"},{"k":"D","t":"Git 完全不需要任何服务器，因此无法做集中式协作"}],"ans":"BC","why":"考 Git 与 SVN 的根本区别（分布式/快照/内容寻址/分支指针），是考研与面试高频。"},{"kind":"choice","q":"三区模型与 reset 三模式","stem":"关于工作区/暂存区/版本库与 git reset 三模式，正确的是？ 请选择并说明。","opts":[{"k":"A","t":"git commit 会把「工作区所有改动」提交，无需 git add"},{"k":"B","t":"git reset --hard HEAD~1 会把 HEAD、暂存区、工作区全部回退到上一个提交，未提交的改动会丢失"},{"k":"C","t":"git reset --soft HEAD~1 只移动 HEAD，暂存区与工作区保持不变（改动仍 staged）"},{"k":"D","t":"git reset --mixed（默认）会移动 HEAD 并重置暂存区，但保留工作区改动"}],"ans":"BCD","why":"考三区归属与 reset 三模式对三区的影响范围，是本章核心。"},{"kind":"output","q":"推断 reset --soft 后的三区状态","stem":"仓库只有一个提交 c1（含 a.txt 内容为 1）。执行序列： ① 编辑 a.txt 内容为 2；② git add a.txt；③ git reset --soft HEAD。 请回答：(1) HEAD 现在指向哪个提交？(2) git status 中 a.txt 属于哪种状态（未修改 / 已暂存待提交 / 工作区已改未暂存）？","opts":[],"ans":"HEAD 仍指向 c1；a.txt 处于「已暂存待提交（staged）」","why":"考 reset 三模式对三区的差异化影响，output 题经典陷阱。"},{"kind":"choice","q":"detached HEAD 与救援","stem":"关于 detached HEAD，正确的是？ 请选择并说明。","opts":[{"k":"A","t":"git checkout <commit-sha> 会进入 detached HEAD，此时 HEAD 直接指向某个 c…"},{"k":"B","t":"在 detached HEAD 状态下提交的 commit 会立即被垃圾回收（GC）删除，无法找回"},{"k":"C","t":"离开 detached 状态（切回分支）后，该状态下产生的提交若未被任何分支/标签引用，确实可能「丢失」，但可用 git…"},{"k":"D","t":"救援 detached 提交的正确做法之一是 git checkout -b rescue <sha> 为其创建分支"}],"ans":"ACD","why":"考 detached HEAD 含义、reflog 救援网与收编手法。"},{"kind":"coding","q":"用 Python 复算 blob SHA（验证内容寻址）","stem":"Git 用 sha1(b'blob ' + len(content) + b'\\0' + content) 计算 blob 对象键。请写一段可直接执行的 Python，验证「相同内容 → 相同 SHA、不同内容 → 不同 SHA」，并打印一个示例 SHA。","opts":[],"ans":"见 reference_code（相同内容 SHA 相等、不同内容不相等）","why":"用可执行 Python 落地内容寻址定义，呼应 concept/01 与 examples/ex01。"},{"kind":"coding","q":"用 Python 模拟 commit→tree→blob 的 Merkle DAG","stem":"请用一段可直接执行的 Python 模拟 Git 的对象链：给定文件内容与提交说明，依次计算 blob、tree、commit 的 SHA-1，并验证「改动任一底层字节会改变根 commit 的 SHA」（即 Merkle 结构的可验证性）。","opts":[],"ans":"见 reference_code（commit SHA 随内容变化而变化）","why":"模拟 Merkle DAG 与 SHA 链，呼应 concept/01 博士生视角。"},{"kind":"coding","q":"模拟 merge-base：commit DAG 上的最近公共祖先（LCA）","stem":"git merge-base A B 求两分支的最近公共祖先，是三方合并的基线。请写一段可直接执行的 Python：给定 parents 映射（node → 父节点列表）与两个起点，实现求最近公共祖先的算法，并用示例 DAG 验证。","opts":[],"ans":"见 reference_code（LCA 返回正确祖先）","why":"实现 merge-base 算法，呼应 concept/03 与 examples/ex06。"},{"kind":"coding","q":"内容寻址去重：统计唯一 blob 数","stem":"Git 内容寻址的天然收益是「相同内容只存一份」。请写一段可直接执行的 Python：给定若干文件及其内容，用 blob SHA 计算唯一 blob 数量与去重率，并断言两个内容相同的文件只计一次。","opts":[],"ans":"见 reference_code（唯一 blob 数正确）","why":"用集合去重模拟内容寻址收益，呼应 concept/01 与 examples/ex02。"}],"works":[{"h":"把 git commit 当成「提交工作区所有改动」","d":"现象：改了文件直接 commit，发现改动没进历史。根因：commit 只固化暂存区（index），未 git add 的改动不会进提交。正确做法：提交前用 git status 确认待提交项；需要全部提交用 git add -A 再 commit，或用 git commit -a（仅已 tracked 文件）。"},{"h":"git reset --hard 把未提交的改动全抹掉","d":"现象：reset 后发现半天的工作没了。根因：--hard 会同时重置 HEAD、暂存区、工作区，工作区未提交的修改被直接丢弃且（若无 reflog 指向）难找回。正确做法：不确定时用 --soft/--mixed；确需 --hard 前先 git stash 或确认改动已提交。"},{"h":"对已经 push 的分支做 reset --hard + 强推","d":"现象：你「整理」了历史，队友 pull 后冲突满天飞甚至丢失提交。根因：reset 改写提交 SHA，强推（git push --force）把共享历史推翻，他人基于旧 SHA 的工作变成孤儿。正确做法：共享分支永远用 git revert 做可协作回滚；必须强推时用 --force-with-lease 且先沟通。"},{"h":"在 detached HEAD 下提交后切走「提交丢了」","d":"现象：checkout 一个老提交做了实验性提交，切回 main 后找不到它。根因：detached 下的提交不属任何分支，离开后无引用指向，最终被 GC。正确做法：提交后立即 git branch rescue <sha> 或 git checkout -b rescue 收编；若已切走，用 git reflog 找到旧 SHA 再…"},{"h":"以为 git checkout -- <file> 会动 HEAD","d":"现象：想恢复某个文件却担心「切了分支」。根因：checkout -- file 与 git restore 只动文件内容，不切换分支、不动 HEAD。正确做法：恢复工作区用 git restore --source=HEAD --worktree <file>；切换分支用 git switch <branch>（这才是动 HEAD 的…"},{"h":"冲突时直接提交含 <<<<<<< 标记的文件","d":"现象：合并冲突后没仔细看就 add+commit，代码里残留冲突标记上线。根因：冲突标记是 Git 的占位符，不是合法代码/数据。正确做法：编辑文件手工消除 <<<<<<</=======/>>>>>>>，确认语义后再 git add+git commit；用 git diff 复核。"},{"h":"git merge 默认快进导致历史「看起来没合并过」","d":"现象：feature 合进 main 后 git log 是一条直线，看不出曾合并。根因：目标分支是源的祖先时 merge 默认快进（只移指针），不产生 merge commit。正确做法：想保留「合并痕迹」用 git merge --no-ff；CI/发布分支通常强制 --no-ff。"},{"h":"对已共享的分支做 rebase 再强推","d":"现象：rebase 自己的提交后 push 被拒，强推后队友历史错乱。根因：rebase 改写提交 SHA（旧提交被新提交取代），已共享的旧提交仍被他人引用，造成分叉。正确做法：只对本地、未 push 的提交 rebase 整理；共享分支用 merge 而非 rebase。"}],"asks":[{"q":"Git 与 SVN 的核心区别是什么？为什么 Git 分支比 SVN 轻量？","a":"分布式 vs 集中式：Git 每个克隆都是完整仓库（含全部历史与对象库），离线可提交、无单点依赖；SVN 是集中式，历史在服务端，提交需联网。 存储模型：Git 存储文件快照并以内容寻址（SHA-1）组织对象（blob/tree/commit/tag）；SVN 主要存储文件差异（delta）并基于版本号/路径寻址。 分支轻量的原因：Git 分支只是 .git/refs/heads/<name> 里…","fu":["Git 的快照存储会不会让仓库体积爆炸？（不会，相同内容只存一份 + packfile delta 压缩）","为什么说 Git 的提交是内容寻址的？（SHA-1 = sha1(类型+长度+内容)，内容定则哈希定）"],"tag":"字节跳动/阿里云"},{"q":"请解释 Git 的工作区、暂存区、版本库三区模型，以及 add/commit 在做什么。","a":"三区定义： - 工作区（working tree）：你直接编辑的目录文件； - 暂存区（index / stage）：下一次 commit 的候选清单，本质是（path → blob SHA）的映射草稿； - 版本库（repository）：对象数据库（.git/objects）+ 引用（.git/refs、HEAD），即已固化的历史。 命令语义： - git add <file>：把工作区改动计…","fu":["为什么要有暂存区这一层？（允许把一次大的改动拆成多个逻辑提交）","git commit -a 和 git add -A 有什么区别？（前者只自动暂存已 tracked 文件，后者含新文件…"],"tag":"腾讯/阿里云"},{"q":"Git 分支为什么这么轻量？分支和 commit 到底是什么关系？","a":"本质：Git 的分支只是一个指向某个 commit 的轻量引用文件（.git/refs/heads/<name>，内容是一行 41 字节的 SHA）。它不拷贝任何数据。 与 commit 的关系：commit 是 DAG 中的节点；分支 = 指向某个节点的指针。N 个分支 = N 个指针指向 DAG 中不同（或相同）的节点，彼此独立、开销极小。 HEAD 的角色：HEAD 是「当前所在位置」的符号…","fu":["为什么删除分支不会立刻删除提交？（引用删除后对象变不可达，GC 才回收）","HEAD 与分支引用解引用的过程是怎样的？（HEAD -> refs/heads/X -> SHA）"],"tag":"美团/字节跳动"},{"q":"快进合并和三方合并（非快进）有什么区别？rebase 和 merge 怎么选？","a":"快进合并（fast-forward）：当目标分支的顶端是源分支顶端的祖先时，git merge 默认只把目标指针直接移到源顶端，不产生新提交——历史是一条直线。 三方合并（three-way / 非快进）：当两边各自有新提交（分叉）时，Git 以共同祖先 merge-base 为基线，生成一个新的合并提交，它有两个 parent，把分叉重新汇合。 rebase vs merge 取舍： - mer…","fu":["merge commit 有几个 parent？章鱼合并呢？（分叉合并 2 个，章鱼合并 >2 个）","rebase 改写历史为什么危险？（旧 SHA 被新 SHA 取代，他人引用变孤儿）"],"tag":"阿里云/腾讯"}]},{"id":"tool-ch04","subj":"tooling","title":"Git 协作：分支策略与冲突处理","summary":"fetch 与 pull 的真实语义（pull = fetch + merge/rebase）；push 的拒绝原因与 --force-with-lease；冲突的产生与解决流程；cherry-pick、stash、reflog 救援误操作…","concepts":[{"id":"tool-ch04/01-fetch-pull-push","file":"01-fetch-pull-push.md","title":"远端协作：三类引用、fetch/pull 语义与 push 的安全边界","kind":"flow","secs":[{"h":"一、pull 不是「拉取」：fetch / pull / push 到底动了什么","s":"远端协作涉及三类引用，混淆它们是一切事故的起点：","c":{"lang":"text","code":"本地仓库                                  远端仓库(origin)\nrefs/heads/main       ──push──▶         refs/heads/main\nrefs/remotes/origin/main ◀──fetch──      refs/heads/main   （快照，只在 fetch/push 时更新）"}},{"h":"二、push 为什么被拒绝，以及 --force-with-lease 为什么比 --for…","s":"push 被拒的唯一常见原因是 non-fast-forward：你要写入的目标引用当前值不是你新值的祖先，","c":{"lang":"bash","code":"git push origin main\n#  ! [rejected]  main -> main (fetch first)   <- 远程有你本地没有的提交\n\ngit fetch origin\ngit log --oneline HEAD..origin/main       # 远程多出来的\ngit log --oneline origin/main..HEAD       # 本地多出来的\n\n# 确实需要强推时用 --force-with-lease\ngit push --force-with-lease origin feature/x"}}]},{"id":"tool-ch04/02-conflict-resolution","file":"02-conflict-resolution.md","title":"冲突的本质：三方合并、冲突标记与解决流程","kind":"timeline","secs":[{"h":"一、冲突的充要条件与三方合并（three-way merge）","s":"Git 的合并不是「比较两份文件的异同」，而是三方合并：给定","c":null},{"h":"二、冲突标记、解决流程与 rerere","s":"冲突时 Git 在工作区写入标记：","c":{"lang":"text","code":"<<<<<<< HEAD            <- ours（当前分支/HEAD 一侧）\n这里是我们的版本\n=======                 <- 分隔两个版本\n这里是对方的版本\n>>>>>>> feature/login   <- theirs（被合并的一侧）"}},{"h":"可运行代码：rebase 冲突的标准处置流程","s":"冲突不是「报错了」，而是 Git 停在半路等你决策；关键是分清继续、跳过、放弃三条出口：","c":{"lang":"bash","code":"git fetch origin\ngit rebase origin/main          # 把自己的提交逐个重放到最新 main 之上\n\n# 一旦冲突，git 会停下并提示哪些文件 unmerged\ngit status                      # 列出 both modified 的文件\ngit diff --name-only --diff-filter=U   # 只列未解决冲突的文件\n\n# 手工解决：删掉 <<<<<<< ======= >>>>>>> 三段标记，保留最终内容\ngit add src/service.ts\n…"}}]},{"id":"tool-ch04/03-cherry-pick-stash-reflog","file":"03-cherry-pick-stash-reflog.md","title":"提交搬运与误操作救援：cherry-pick / stash / reflog","kind":"stack","secs":[{"h":"一、cherry-pick / revert / rebase：三种「复制/抵消」语义","s":"三者都会对已有的改动做文章，但语义完全不同：","c":null},{"h":"二、stash 栈与 reflog 救援网","s":"git stash 把「工作区 + 暂存区」的改动打成一个快照压栈，然后把已跟踪文件还原到 HEAD。","c":{"lang":"bash","code":"git stash push -m \"wip: 表单校验\"   # 压栈（-u 才会包含未跟踪文件）\ngit stash list                       # stash@{0} ... 从新到旧\ngit stash pop                        # 取出栈顶并删除该记录\ngit stash apply stash@{1}            # 取出指定条目但**保留**记录\ngit stash drop stash@{1}             # 删除指定条目"}}]},{"id":"tool-ch04/04-branch-strategy-and-repo-hygiene","file":"04-branch-strategy-and-repo-hygiene.md","title":"分支策略、提交规范与仓库卫生","kind":"compare","secs":[{"h":"一、分支策略选型（Git Flow / GitHub Flow / Trunk Based）…","s":"三种主流策略的本质差异是长期分支数量与发布单元：","c":{"lang":"text","code":"<type>[optional scope][!]: <description>\n\n[optional body]\n\n[optional footer(s)]   # BREAKING CHANGE: xxx / Refs #123"}},{"h":"二、仓库卫生：.gitignore、.gitattributes 与 Git LFS","s":"三份配置解决三类完全不同的问题：","c":null}]}],"exams":[{"kind":"choice","q":"fetch / pull / push 各自动了什么","stem":"关于 Git 远端协作的三类引用与三条命令，下列说法正确的是？ 请选择全部正确项并说明理由。","opts":[{"k":"A","t":"git fetch 会把远端的新提交合并进当前分支"},{"k":"B","t":"git fetch 只更新远端跟踪引用 refs/remotes/origin/，不碰本地分支与工作区"},{"k":"C","t":"git pull = git fetch +（git merge 或 git rebase），默认行为由 pull.re…"},{"k":"D","t":"git pull --rebase 会改写本地尚未推送的提交 SHA，使历史保持线性"}],"ans":"BCD","why":"考三类引用与 pull 的真实分解式，是本章最基础的考点，也是 tools/DevOps 面试开场题。"},{"kind":"output","q":"推断 pull 之后的快照 与 ahead/behind","stem":"仓库状态如下（字母为提交）： text origin/main: X -> A -> B -> C 你的 main : X -> A -> D 此时 refs/remotes/origin/main 指向 A（你上次 fetch 的位置），远端真实引用指向 C。 依次执行：① git fetch；② git pull --rebase；③ git log --oneline main..origi…","opts":[],"ans":"① origin/main -> C，本地 main 仍为 D；② main 形态为 X -> A -> B -> C -> D'（D 被改写为新的 D'，SHA 变化）；③ 输出为空","why":"考 fetch 与 pull --rebase 对三类引用的差异化影响，以及 A..B 左右集合差（ahead/behind）的口径。"},{"kind":"choice","q":"push 被拒、强推与共享分支回滚","stem":"关于 push 被拒绝与强行推送，下列说法正确的是？ 请选择全部正确项。","opts":[{"k":"A","t":"push 被拒最常见的原因是 non-fast-forward：远端引用当前值不是你本地 tip 的祖先"},{"k":"B","t":"git push --force 一定会先把别人的提交合并进来，因此不会丢东西"},{"k":"C","t":"--force-with-lease 会校验「远端引用 == 我本地记录的 origin/main」，不一致则拒绝（st…"},{"k":"D","t":"对已经发布的共享分支做回滚，正确做法是 git revert 追加反向提交，而不是 reset --hard + 强推"}],"ans":"ACD","why":"考 push 的安全边界与共享分支回滚标准做法，是本章最常考的安全题。"},{"kind":"fix_error","q":"修正一段有四处错误的冲突处理流程","stem":"下面是某同学处理 git merge feature 冲突的流程，逐项指出错误并给出正确写法： bash # 1. 冲突后直接选择自己这一侧整段 $ git checkout --ours config/app.conf # 2. 删除多余文件后直接提交 $ git commit -m \"fix conflict\" # 3. 发现合错了，回退这次 merge $ git reset --hard…","opts":[],"ans":"① 用 --ours 整段丢弃对方改动（应手工合并或开 diff3 风格）；② 冲突解决后必须 git add <file> 再 commit；③ 已 push 的 merge 应 git revert -m 1 <sha>，禁止 reset+强推共享分支；④ rebase 下 ours/theirs 语义颠倒，不能按…","why":"把「冲突解决流程 + rebase 语义颠倒 + 共享分支回滚」三个高频坑放进同一道改错题，贴合真实事故复盘。"},{"kind":"coding","q":"用 Python 模拟 stash 的 LIFO 栈语义","stem":"请写一段可直接执行的 Python，实现一个极简 git stash 栈：支持 push / pop / list（stash@{0} 为最近压入的一条），并用两次压栈验证取出顺序是 LIFO（后进先出）而非 FIFO。要求带断言验证结果。","opts":[],"ans":"见 reference_code（两次 pop 按 LIFO 顺序取出，断言通过）","why":"用可执行代码落地 stash 的栈语义，呼应 concept/03 与 examples/ex08。"},{"kind":"coding","q":"实现 Conventional Commits 提交信息校验器","stem":"请用可直接执行的 Python + 正则实现一个 Conventional Commits 首行校验器：<type>[optional scope][!]: <description>，其中 type ∈ {feat, fix, docs, style, refactor, perf, test, build, ci, chore, revert}。要求至少包含两组正例、两组反例（缺类型 / 缺冒…","opts":[],"ans":"见 reference_code（4 条用例判定全部符合预期，断言通过）","why":"把提交规范变成可执行判据，呼应 concept/04 与 examples/ex11。"},{"kind":"coding","q":"合并基线：commit DAG 上的 merge-base（最近公共祖先）","stem":"三方合并需要基线 merge-base(ours, theirs)。给定 DAG 的 parents 映射（节点 → 父节点列表），请写可直接执行的 Python： 1. 求任意两节点的 merge-base（要求能够处理存在多个极大共同祖先的 criss-cross 历史，用 merge_base_all 返回全部）； 2. 用给定 DAG 验证 merge_base('B','C') == '…","opts":[],"ans":"见 reference_code（单基点返回 A；criss-cross 返回两个并列基点，断言通过）","why":"把 merge-base 还原成图论算法题，呼应 concept/02 的合并基线与 examples/ex02。"},{"kind":"coding","q":"三方合并算法：自动合并与冲突判定的正反对照","stem":"请写可直接执行的 Python（可用标准库 difflib），基于行级 diff 实现三方合并 merge3(base, ours, theirs)： 1. 两侧改动落在不同区域时应当自动合并； 2. 两侧改动同一区域且结果不同时必须产出 <<<<<<< / ======= / >>>>>>> 标记； 3. 两侧改动同一区域但结果完全相同时不得判冲突。 用至少三组用例验证（不同区域自动合并、同行异…","opts":[],"ans":"见 reference_code（区域分离自动合并、同行异值报冲突、同行同值不冲突，断言通过）","why":"把 Git 的合并内核还原成可实现、可验证的算法题，呼应 concept/02 与 examples/ex03、ex04。"}],"works":[{"h":"把 git pull 当成「只是把远端拉取下来」","d":"现象：习惯性 git pull，结果本地被自动合并/重放，冲突在你没预料的时候出现，甚至多出一个 merge commit。根因：pull = fetch +（merge 或 rebase），它会移动你的本地分支并改写工作区。正确做法：先 git fetch，用 git log --oneline main..origin/main…"},{"h":"push 被拒就加 --force","d":"现象：推上去之后队友当天的工作从远端消失。根因：push 被拒 = non-fast-forward = 远端有你没整合的提交，--force 是无校验的直接覆盖。正确做法：git fetch → git rebase origin/main（或 merge）→ 解决冲突 → 再 push；确需强推时用 --force-with-le…"},{"h":"以为 --force-with-lease 是「安全的强推」，于是放心地改写共享分支","d":"现象：lease 校验通过了，历史照样被改写，队友 pull 后一堆冲突。根因：lease 只保证「不覆盖我没看过的提交」——如果你刚 fetch 过，租约天然一致，保护退化为允许覆盖。正确做法：共享分支回滚一律用 git revert（追加历史）；把 main/release 设为保护分支，从平台层面禁止强推。"},{"h":"对已经 push 的分支做 rebase 再推","d":"现象：本地历史干净了，队友的提交变成孤儿，push 被拒后你强推，团队历史分裂。根因：rebase 改写 SHA，别人基于旧 SHA 的工作失去根基。正确做法：黄金法则——只对本地尚未推送的提交 rebase；已共享就用 merge。确需整理时全组沟通，重排后所有人 git reset --hard origin/<branch> 对…"},{"h":"特性分支长期不与主干同步","d":"现象：两周后一次性合并，几百行冲突、合并花一整天还容易合错。根因：冲突概率与合并成本随「分支寿命 × 并行改动量」增长，集成得越晚代价越大。正确做法：每天 git fetch + rebase（或 merge）主干；分支寿命控制在 3 天以内，配合 feature flag 做未完成功能隔离。"},{"h":"冲突解决直接用 git checkout --ours/--theirs 挑一边","d":"现象：「解决」完上线，发现对方的修复没了。根因：这两个选项是整段丢弃另一侧，不是合并；而且 union 也可能产出重复定义。正确做法：打开编辑器手工合并两侧语义（可开 merge.conflictStyle diff3 看到共同祖先那一行）；--ours/--theirs 只用于明确知道单边正确的情况。"},{"h":"删掉冲突标记就以为解决了，忘了 git add","d":"现象：git commit 报 Committing is not possible because you have unmerged files。根因：Unmerged 路径在 index 里有 stage 1/2/3 三个版本，只有 git add 才会把它归一到 stage 0。正确做法：编辑 → git add <file>…"},{"h":"把含 <<<<<<< 标记的文件提交上线","d":"现象：构建失败或线上配置文件出现乱码般的标记。根因：冲突标记是 Git 的占位符，不是合法代码/配置。正确做法：提交前用 grep -rn '^<<<<<<<\\|^>>>>>>>' . 自检，并把该检查做成 pre-commit 钩子或 CI 步骤。"}],"asks":[{"q":"请说明 git fetch、git pull 与 git pull --rebase 的区别，并说明为什么团队里推荐「先 fetch 再看差异」。","a":"三类引用：本地分支 refs/heads/、远端跟踪引用 refs/remotes/origin/（上次通信时远端状态的快照）、远端真实引用。 - fetch：搬运远端有而本地没有的对象，只更新远端跟踪引用，不碰本地分支、暂存区与工作区 → 幂等、随时可安全执行。 - pull = fetch + 一次整合：默认 merge（非快进时产生 merge commit），配置 pull.rebase=…","fu":["如果你已经 pull 产生了一个 merge commit 但想改成线性历史，怎么办？","git pull --rebase 在 CI 流水线里有什么风险？"],"tag":"通用/字节"},{"q":"git push 被 rejected 了，你会怎么处理？请比较 --force 与 --force-with-lease，并说明共享分支的正确回滚方式。","a":"被拒原因：绝大多数是 non-fast-forward —— 远端引用当前值不是你本地 tip 的祖先，即远端出现了你尚未整合的提交（其余可能：保护分支权限、hook 校验失败）。 处理顺序： 1. git fetch； 2. git rev-list --left-right --count <branch>...origin/<branch> 看落后/领先； 3. 整合：个人分支用 git r…","fu":["--force-with-lease 在刚 fetch 过的情况下为什么「保护失效」？","出了问题如何找回远端丢失的提交？"],"tag":"通用/阿里"},{"q":"Git 什么时候会产生冲突？请描述完整的冲突解决流程，并说明 rebase 场景下 ours/theirs 为什么会「反了」。","a":"充要条件：三方合并以 merge-base 为基线，对比 ours（当前 HEAD）与 theirs（被合入方）。当双方改动了 base 的同一区域且结果不同（含一侧删除、另一侧修改）时冲突。注意：「改了同一个文件」既不充分也不必要——不同区域自动合并；改同一处但结果完全相同也不冲突。 流程： 1. git status 看哪些路径 Unmerged； 2. 手工编辑（建议开 merge.conf…","fu":["存在多个共同祖先（criss-cross）时 Git 怎么处理？","为什么「自动合并成功」的代码仍可能编译失败？"],"tag":"通用/字节"},{"q":"cherry-pick、revert、rebase、merge 都涉及「把改动搬到别处」，请说明它们的语义差异与各自的适用场景。","a":"| 命令 | 语义 | 是否改写历史 | 场景 | |---|---|---|---| | merge | 保拓扑合并，非快进时产生有两个 parent 的 merge commit | 否 | 集成分支、保留并行开发真相 | | rebase | 把一段提交逐个「重放」到新基点，等价于循环 cherry-pick | 是 | 整理本地未推送提交、拉平历史 | | cherry-pick | 复制…","fu":["为什么 cherry-pick 后的提交 SHA 与原提交不同？","如何把 feature 分支中间某一段连续提交整体搬到另一分支？"],"tag":"通用/京东"}]},{"id":"tool-ch05","subj":"tooling","title":"Docker 基础：镜像、容器与 Dockerfile","summary":"容器 vs 虚拟机的隔离原理（namespace 隔离视图 + cgroup 限制资源）；镜像的分层结构与联合文件系统、内容寻址；容器生命周期与常用命令（run/exec/logs/stop/rm）；Dockerfile 指令与构建缓存、多…","concepts":[{"id":"tool-ch05/01-container-vs-vm-isolation","file":"01-container-vs-vm-isolation.md","title":"隔离原理：namespace、cgroup 与「容器不是虚拟机」","kind":"compare","secs":[{"h":"一、容器 = namespace（隔离视图）+ cgroup（限制用量）+ 共享内核","s":"容器并不是一项新技术，而是 Linux 内核三个能力的组合封装：","c":{"lang":"bash","code":"# 容器内看 PID：从 1 开始 —— PID namespace 生效\ndocker run --rm alpine ps -o pid,comm\n\n# 宿主机上看同一个容器进程：只是一个普通的高位 PID\ndocker inspect -f '{{.State.Pid}}' mycontainer\n\n# 直接读 cgroup 上限：容器内看到的就是配置值\ndocker run --rm -m 256m alpine cat /sys/fs/cgroup/memory.max"}},{"h":"二、代价对比：启动速度、体积与隔离强度的三方权衡","s":"examples/ex02 实测：同样一份应用，VM 镜像 10240.0MB、容器镜像 180.4MB（56.8x）；","c":null}]},{"id":"tool-ch05/02-image-layers-overlayfs","file":"02-image-layers-overlayfs.md","title":"镜像分层：内容寻址、overlayfs 与写时复制","kind":"stack","secs":[{"h":"一、镜像 = 只读层的有序栈 + 内容寻址","s":"一条 Dockerfile 指令（在经典构建器下）产出一层。层是只读的增量：记录「新增/修改了哪些文件」。","c":{"lang":"text","code":"  ┌──────────────────────────────┐\n  │ 层5 COPY app.py .      (可写? 否，只读) │\n  ├──────────────────────────────┤\n  │ 层4 RUN pip install          │\n  ├──────────────────────────────┤\n  │ 层3 COPY requirements.txt    │\n  ├──────────────────────────────┤\n  │ 层2 RUN apt-get install curl │\n  ├──────────────────────────────┤\n…"}},{"h":"二、联合文件系统 overlayfs：lower / upper / merged / wo…","s":"内核把多层拼成一个统一视图靠的是联合文件系统（主流为 overlayfs）：","c":{"lang":"bash","code":"mkdir -p /tmp/ovl/{lower,upper,work,merged}\necho \"原内容\" > /tmp/ovl/lower/base.txt          # 模拟只读镜像层\n\nsudo mount -t overlay overlay \\\n  -o lowerdir=/tmp/ovl/lower,upperdir=/tmp/ovl/upper,workdir=/tmp/ovl/work \\\n  /tmp/ovl/merged\n\ncat /tmp/ovl/merged/base.txt    # ① 读：命中 lower\necho \"改过了\" > /tmp/ovl/merged/base.txt\n…"}}]},{"id":"tool-ch05/03-lifecycle-volume-network","file":"03-lifecycle-volume-network.md","title":"镜像与容器：生命周期、数据卷与网络","kind":"timeline","secs":[{"h":"一、镜像是类，容器是对象：可写层的归属","s":"一套 namespace/cgroup + 一份元数据（环境变量、端口映射、挂载）。","c":null},{"h":"二、生命周期与常用命令","s":"如果 PID 1 是 /bin/sh，信号不会转发，docker stop 每次都要等满 10 秒超时——","c":null},{"h":"三、数据卷与网络模式","s":"要绝不落盘的临时敏感数据用 tmpfs。","c":{"lang":"bash","code":"# 用一次性容器挂载具名卷做备份，不需要停业务\ndocker run --rm -v appdata:/data -v \"$PWD:/backup\" alpine \\\n  tar czf /backup/appdata.tgz -C /data .\n\n# 恢复同理；解包前必须先停写入方，否则会恢复出一半数据\ndocker run --rm -v appdata:/data -v \"$PWD:/backup\" alpine \\\n  sh -c 'rm -rf /data/* && tar xzf /backup/appdata.tgz -C /data'"}}]},{"id":"tool-ch05/04-dockerfile-cache-size","file":"04-dockerfile-cache-size.md","title":"Dockerfile：指令语义、构建缓存与镜像瘦身","kind":"compare","secs":[{"h":"一、指令语义：CMD vs ENTRYPOINT、COPY vs ADD","s":"1. 有 ENTRYPOINT（exec 形式）时，CMD 的内容整体作为参数追加在其后；","c":null},{"h":"二、构建缓存与多阶段构建","s":"1. 每层的缓存键 = 父层键 + 本指令键，父层失效则其后全部重建；","c":{"lang":"dockerfile","code":"# 构建阶段：带全套工具链，这一层体积可以很大\nFROM golang:1.22 AS build\nWORKDIR /src\nCOPY go.mod go.sum ./\nRUN go mod download                 # 依赖层：只改源码时这一层仍命中缓存\nCOPY . .\nRUN CGO_ENABLED=0 go build -o /out/app ./cmd/app\n\n# 运行阶段：只拷贝产物，工具链、源码、缓存全部留在上一阶段\n…"}},{"h":"三、体积优化与安全基线","s":"1. 选小基础镜像：alpine（~5MB，musl libc）或 distroless（~2MB，无 shell）；","c":{"lang":"bash","code":"# CI 里的缓存是另一回事：每次都是全新机器，本机层缓存根本不存在\n# 必须显式把缓存「推出去、再拉回来」\ndocker buildx build \\\n  --cache-from type=registry,ref=registry.example.com/app:buildcache \\\n  --cache-to   type=registry,ref=registry.example.com/app:buildcache,mode=max \\\n  --push -t registry.example.com/app:$TAG .\n\n# 排查「这一层为什么没命中」：看构建日志里的 CACHED 标记\ndocker build --progress=plain -t myapp:1.0 . 2>&1 | grep -E \"CACHED|RUN|COPY\""}}]}],"exams":[{"kind":"choice","q":"容器与虚拟机的本质区别","stem":"关于容器与虚拟机的区别，下列说法正确的是？ 请选择并说明。","opts":[{"k":"A","t":"容器拥有独立的 Guest OS 内核，因此隔离强度高于虚拟机"},{"k":"B","t":"容器依靠 namespace 隔离「视图」、cgroup 限制「用量」，并共享宿主内核"},{"k":"C","t":"虚拟机需要引导一份完整的 Guest 内核，因此启动更慢、镜像体积更大"},{"k":"D","t":"容器可以在 Windows 宿主上直接运行依赖 Linux 系统调用的镜像，无需任何虚拟机"}],"ans":"BC","why":"考容器的两根支柱（namespace/cgroup）与「共享内核」这一根本差异，是本章第一考点。"},{"kind":"choice","q":"镜像分层、overlayfs 与写时复制","stem":"关于镜像分层与 overlayfs，下列说法正确的是？ 请选择并说明。","opts":[{"k":"A","t":"镜像层是只读的，多个容器可以共享同一份只读层，各自只多出一个可写层"},{"k":"B","t":"修改一个来自 lower 层的文件时，overlayfs 会先把它复制到 upper 层再改（写时复制），lower 永…"},{"k":"C","t":"在 Dockerfile 里用 RUN rm -rf /big 删除大目录可以有效减小最终镜像体积"},{"k":"D","t":"删除一个来自 lower 层的文件时，是在 upper 层放一个 whiteout 把它遮蔽，下层数据依然存在"}],"ans":"ABD","why":"考 overlayfs 的 lower/upper/merged 语义与「rm 不瘦身」的根因。"},{"kind":"choice","q":"CMD 与 ENTRYPOINT 的组合规则","stem":"镜像里写了 ENTRYPOINT [\"python\"]、CMD [\"app.py\"]，执行 docker run img -u 时最终运行的命令是什么？","opts":[{"k":"A","t":"python app.py -u"},{"k":"B","t":"python -u"},{"k":"C","t":"-u"},{"k":"D","t":"python app.py（docker run 尾部参数被忽略）"}],"ans":"B","why":"考 CMD/ENTRYPOINT 的组合与覆盖规则，以及 shell 形式的信号副作用。"},{"kind":"choice","q":"shell 形式的 ENTRYPOINT 会带来什么","stem":"把上一题改成 shell 形式 ENTRYPOINT python app.py 后，下列哪种说法正确？","opts":[{"k":"A","t":"等价于 exec 形式，CMD 仍会作为参数追加"},{"k":"B","t":"等价于 /bin/sh -c \"python app.py\"，CMD 被完全忽略；且 PID 1 是 /bin/sh，S…"},{"k":"C","t":"镜像构建会直接失败，因为 ENTRYPOINT 不支持 shell 形式"},{"k":"D","t":"CMD 会覆盖 ENTRYPOINT，最终只执行 CMD 里的命令"}],"ans":"B","why":"shell 形式 ENTRYPOINT 的双重副作用：CMD 失效 + 信号不转发。"},{"kind":"output","q":"构建缓存：判断哪些层命中、从第几层重建","stem":"有如下 Dockerfile（构建上下文含 requirements.txt、src/app.py、README.md）： dockerfile FROM python:3.13-slim WORKDIR /app COPY requirements.txt . RUN pip install --no-cache-dir -r requirements.txt COPY src/ ./src/…","opts":[],"ans":"第 1~4 层命中，第 5、6 层失效；首个失效层为第 5 层；不需要重新执行 pip install","why":"考缓存键的构成（父层链 + 指令内容/文件内容）与「依赖先于源码」的第一原则。"},{"kind":"fix_error","q":"改错：找出这份 Dockerfile 里的六个问题","stem":"下面这份 Dockerfile 能构建成功，但有六个明确的问题（涵盖体积、可复现性、缓存、安全）： dockerfile FROM ubuntu:latest RUN apt-get update RUN apt-get install -y curl vim ADD ./config.ini /app/config.ini COPY . /app WORKDIR /app RUN pip ins…","opts":[],"ans":"latest 标签 / apt update 与 install 分两条 RUN / ADD 滥用 / 缺少 .dockerignore / 未清包缓存 / 以 root 运行（另：COPY . 在装依赖之前，缓存易失效）","why":"综合考察体积、可复现性、缓存与安全四条主线，是本章最典型的改错题。"},{"kind":"coding","q":"层依赖链：计算最小重建层数","stem":"设计一个函数 min_rebuild_layers(instructions, context_before, context_after)： - instructions 为 Dockerfile 指令序列 [(\"FROM\", arg), (\"COPY\", arg), (\"RUN\", arg), ...]； - context_before / context_after 为构建上下文的「路径…","opts":[],"ans":"正例 (5, 2)；反例 (3, 3)","why":"把「构建缓存」形式化为一个可计算的链失效问题，是本章最硬的可实测算法点。"},{"kind":"coding","q":"多阶段构建：最终镜像体积与最小体积选择","stem":"实现 multi_stage_size(stages, final_stage, artifacts)： - stages 为 {阶段名: (基础镜像体积MB, [该阶段各层体积MB])}； - artifacts 为 [(源阶段, 产物体积MB)]，表示最终阶段用 COPY --from 取出的产物； - 最终镜像体积 = 最终阶段基础镜像体积 + 最终阶段自身各层体积 + 所有 artifac…","opts":[],"ans":"多阶段 14.0MB，单阶段 1555.6MB，降幅 99.1%","why":"把「多阶段瘦身」变成可计算的体积模型，同时考察对「中间层不入最终镜像」的理解。"}],"works":[{"h":"把容器当成轻量虚拟机，以为它有独立内核","d":"现象：在容器里 uname -r 看到的却是宿主内核版本，想装内核模块失败。根因：容器共享宿主内核，「镜像里的 OS」只是 rootfs（glibc、/bin、包管理器），不含内核。正确做法：需要不同内核/内核模块/强隔离时用虚拟机或 Kata/gVisor；不要把容器当作完整的独立机器。"},{"h":"只设了 memory.max 却不管应用感知","d":"现象：容器内存上限 512MiB，JVM/Node 仍按宿主内存算堆，一启动就被 OOM-kill（退出码 137）。根因：cgroup 限制是内核强制的，但运行时默认读取的是宿主可见资源。正确做法：开启容器感知（JVM UseContainerSupport、MaxRAMPercentage；Node --max-old-space…"},{"h":"把数据写在容器可写层","d":"现象：docker rm 之后数据库数据全没了。根因：所有运行时写入都落在容器的 overlay upper 层，该层与容器同生共死。正确做法：数据库数据、上传文件、需要留存的日志一律挂 volume 或 bind mount；容器保持无状态。"},{"h":"用 RUN rm -rf 想减小镜像体积","d":"现象：删了几百 MB 的编译期文件，docker images 显示体积没变。根因：删除来自只读层的文件只在 upper 生成一个 whiteout 遮蔽，下层数据依旧保存在镜像里。正确做法：用多阶段构建让这些文件根本不进入最终镜像；这是唯一能真正排除体积的方法。"},{"h":"COPY . . 写在安装依赖之前","d":"现象：改一行源码就要重装全部依赖，构建从几秒变成几分钟。根因：COPY . . 的缓存键取决于整个上下文的内容，源码一变该层失效，其后所有层（含 pip install）全部重建。正确做法：先 COPY requirements.txt . → RUN pip install → 再 COPY src/ .，把变化频率低的指令放前面。"},{"h":"apt-get update 与 apt-get install 分成两条 RUN","d":"现象：构建时装的包版本莫名其妙，某天突然失败。根因：update 那层的包索引被长期缓存，与后续的 install 处于不同时间点，产生不可复现的组合。正确做法：写在同一条 RUN：apt-get update && apt-get install -y --no-install-recommends <pkg> && rm -rf…"},{"h":"没有 .dockerignore","d":"现象：构建上下文几百 MB，改个日志文件就击穿整条缓存链。根因：.git、node_modules、__pycache__、本地日志全被送进上下文，任何文件变动都会让 COPY . . 失效。正确做法：必配 .dockerignore；注意 不跨 /，子目录要写 /.log。"},{"h":"基础镜像用 latest 标签","d":"现象：同一份 Dockerfile 两周后构建出的镜像行为变了，甚至起不来。根因：latest 是浮动标签，上游一更新你的产物就变了，构建不可复现。正确做法：固定到具体版本（如 python:3.13.1-slim），更严格用 @sha256:<digest>。"}],"asks":[{"q":"容器和虚拟机的本质区别是什么？为什么容器启动更快、体积更小？","a":"隔离层次不同： - 虚拟机在硬件抽象层做隔离（VMX/SVM、影子页表、虚拟设备），每个实例都要引导一份完整的 Guest 内核； - 容器在系统调用层做隔离：namespace 让进程只看见属于自己的资源视图（mount/pid/net/ipc/uts/user 六类），cgroup 限制它能用多少（cpu/memory/pids/io），内核由宿主共享。 因此代价不同： - 启动：虚拟机要走「…","fu":["容器里能装内核模块吗？（不能，内核是共享的，除非用特权容器且模块与宿主内核完全匹配）","容器中的 PID 1 与宿主的 PID 1 是什么关系？（不同 pid namespace，容器内 PID 1 在宿主上…"],"tag":"通用/字节跳动"},{"q":"镜像为什么是分层的？在 Dockerfile 里用 RUN rm -rf 删掉大文件，镜像体积会变小吗？","a":"分层的目的：把「共享」与「可变」分离。每层只读、由内容摘要（sha256）寻址，因此可以被任意多个镜像和容器共享，推送/拉取只传缺失的层，还能天然去重与校验。 不会变小。原因在 overlayfs 的删除语义： - 只读层（lower）不可写入任何元数据，删除来自 lower 的文件只能在容器/构建的可写层（upper）放一个 whiteout 把它遮蔽； - whiteout 只是一个「遮蔽标记…","fu":["COPY 一个大文件进镜像再 RUN rm，能用 docker history 看出来吗？（能，那一层的大小就是文件本身…","多个容器跑同一个镜像，磁盘占用会翻倍吗？（不会，只读层共享，每个容器只多一个可写层）"],"tag":"通用/美团"},{"q":"为什么 Dockerfile 里要先 COPY 依赖清单、装依赖，再 COPY 源码？背后的缓存规则是什么？","a":"缓存规则（三层）： 1. 每层的缓存键 = 父层键 + 本层键，父层失效则其后全部重建； 2. RUN 的键是命令行字符串； 3. COPY/ADD 的键是被拷贝文件内容的摘要——不是路径、也不是 mtime。 推论：只要被 COPY 的任一文件变了，该层及其后所有层都白干。所以要把变化频率低的指令放前面： dockerfile COPY requirements.txt . RUN pip in…","fu":["改了 Dockerfile 里 RUN 命令的一个空格，缓存会失效吗？（会，RUN 的键就是命令行字符串本身）","ARG 变化会让哪些层失效？（从第一个使用该 ARG 的层开始，其后全部失效）"],"tag":"通用/腾讯"},{"q":"容器删除后数据还在吗？volume、bind mount、tmpfs 和容器可写层有什么区别？","a":"生命周期归属不同： | 类型 | 存放位置 | 容器删除后 | 典型用途 | |---|---|---|---| | volume（命名卷） | /var/lib/docker/volumes/<name>/_data | 保留 | 数据库数据、跨容器共享 | | bind mount | 宿主任意路径 | 保留 | 挂载配置、源码热重载 | | tmpfs | 宿主内存 | 丢失 | 密钥、se…","fu":["docker rm -v 会删除命名卷吗？（会删除匿名卷；命名卷仍保留，需 volume rm）","多个容器挂同一个 volume 会冲突吗？（不冲突，这就是共享数据的手段，但要自己处理并发写）"],"tag":"通用/阿里云"}]},{"id":"tool-ch06","subj":"tooling","title":"Docker Compose 与部署实践","summary":"Compose 编排多服务（依赖顺序、网络、数据卷、环境变量、健康检查）；restart 策略与日志驱动；镜像仓库（Registry/Harbor）与 CI 集成；资源限制与 OOM；容器化下的配置外置（12-Factor App）；从本地…","concepts":[{"id":"tool-ch06/01-service-dependency-and-network","file":"01-service-dependency-and-network.md","title":"服务定义、依赖顺序与网络","kind":"compare","secs":[{"h":"一、服务定义与依赖顺序：depends_on 只保证启动顺序，不保证就绪","s":"compose 文件的 services 段是一组声明式期望状态：每个服务给出镜像、端口、卷、环境变量、","c":null},{"h":"二、网络：自定义 bridge、服务名即 DNS、暴露 vs 发布","s":"compose 为每个 project 默认创建一个 <project>_default 的自定义 bridge 网络，","c":{"lang":"yaml","code":"services:\n  api:\n    build: .\n    depends_on:\n      db:\n        condition: service_healthy     # 等就绪，不只是等启动\n    environment:\n      DB_HOST: db                      # 服务名即 DNS 名，同网络内直接解析\n  db:\n…"}},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"from collections import defaultdict\n\n\ndef parse_services(raw):\n    \"\"\"把 compose 的 services 段归一成内部模型。\n\n    depends_on 有两种写法：短语法（列表）与长语法（映射，键是服务名，\n    值是 condition）。归一后统一成列表，保留 condition 供 ex02 使用。\n    \"\"\"\n…"}}]},{"id":"tool-ch06/02-volume-env-healthcheck","file":"02-volume-env-healthcheck.md","title":"数据卷、环境变量与健康检查","kind":"compare","secs":[{"h":"一、数据卷：命名卷 vs 绑定挂载，持久化与备份","s":"容器可写层与容器同生共死（docker rm 即丢），所以一切要留存的数据都必须写到卷里。","c":null},{"h":"二、环境变量：五级优先级与变量插值","s":"Compose 的环境变量有明确的五级优先级（Docker 官方口径，高 → 低）：","c":null},{"h":"三、健康检查：把「是否就绪」变成可观测谓词","s":"healthcheck 把应用状态提升为编排器可判定的布尔值，五个字段各司其职：","c":{"lang":"yaml","code":"services:\n  api:\n    image: myapp:1.0\n    env_file: [.env]                    # 优先级低于 environment\n    environment:\n      LOG_LEVEL: ${LOG_LEVEL:-info}     # 未设置时取默认值\n    volumes:\n      - appdata:/var/lib/app\n    healthcheck:\n…"}},{"h":"可运行代码：一份带卷、环境变量与健康检查的 compose","s":"这几个字段互相牵连：卷决定数据活多久，env_file 决定敏感值进不进 git，","c":{"lang":"yaml","code":"services:\n  app:\n    image: myapp:1.4.0\n    environment:\n      - SPRING_PROFILES_ACTIVE=prod\n      - DB_URL=jdbc:mysql://db:3306/orders\n    env_file:\n      - .env                      # 密码等敏感值走文件，.env 写进 .gitignore\n    volumes:\n…"}}]},{"id":"tool-ch06/03-restart-logging-registry-ci","file":"03-restart-logging-registry-ci.md","title":"restart 策略、日志驱动、镜像仓库与 CI","kind":"flow","secs":[{"h":"一、restart 策略与日志驱动：退避、熔断与磁盘风险","s":"compose 的 restart 有四种取值：","c":null},{"h":"二、镜像仓库与 CI 集成：打标签、推送、部署","s":"镜像仓库是镜像的「版本控制系统」：","c":{"lang":"bash","code":"# 用 git 短 SHA 作标签：任一线上镜像都能反查到源码\nTAG=$(git rev-parse --short HEAD)\ndocker build \\\n  -t registry.example.com/app:$TAG \\\n  -t registry.example.com/app:latest .\ndocker push registry.example.com/app:$TAG"}}]},{"id":"tool-ch06/04-resource-config-k8s-troubleshooting","file":"04-resource-config-k8s-troubleshooting.md","title":"资源限制与 OOM、配置外置、K8s 演进与故障排查","kind":"flow","secs":[{"h":"一、资源限制与 OOM：mem_limit/cpus 与退出码 137","s":"compose 用 mem_limit（或新版 deploy.resources.limits.memory）与 cpus 限制容器用量，","c":null},{"h":"二、配置外置（12-Factor）与密钥管理","s":"12-Factor App 给出云原生应用的一组约定，与容器化直接相关的几条：","c":null},{"h":"三、从 compose 到 K8s：概念映射与演进路径","s":"compose 解决的是单机多容器，K8s 解决的是多机编排。","c":null},{"h":"四、常见故障排查：症状 → 根因 → 处置","s":"把高频故障整理成可判定的规则（examples/ex13 实测规则库判定）：","c":{"lang":"bash","code":"# 退出码 137 = 128 + 9，即被 SIGKILL；容器语境下九成是 OOM\ndocker inspect -f '{{.State.OOMKilled}} {{.State.ExitCode}}' mycontainer\n# 输出 true 137  -> 确认是内存超限\n\n# 再看限制与实际占用\ndocker stats --no-stream mycontainer"}}]}],"exams":[{"kind":"choice","q":"depends_on 的局限与 condition: service_healthy","stem":"一个 compose 文件里 api 依赖 db，写法是短语法 depends_on: [db]。docker compose up 之后一切正常，但 api 日志的第一行是 connection refused to db。 下列说法正确的是？（多选） A. 短语法 depends_on 等价于 condition: service_started，只保证 db 的容器进程已创建 B. serv…","opts":[{"k":"A","t":"只保证容器进程已创建"},{"k":"B","t":"service_started 意味着能接受连接"},{"k":"C","t":"改用 service_healthy 且被依赖方配 healthcheck"},{"k":"D","t":"应用侧仍要重试与退避"}],"ans":"ACD","why":"考 depends_on 的两种 condition 语义，是本章第一考点。"},{"kind":"choice","q":"环境变量五级优先级","stem":"按 Docker 官方文档，Compose 环境变量的优先级从高到低依次是？ A. 镜像 ENV > env_file > environment > 插值 > CLI -e B. CLI -e > 插值（shell 优先于 .env）> environment > env_file > 镜像 ENV C. environment > CLI -e > env_file > 插值 > 镜像 ENV…","opts":[{"k":"A","t":"镜像 ENV 最高"},{"k":"B","t":"CLI -e 最高，插值次之（shell 优先于 .env）"},{"k":"C","t":"environment 高于 CLI -e"},{"k":"D","t":".env 高于 shell"}],"ans":"B","why":"考五级优先级与「shell 压 .env」这一最容易记反的细节。"},{"kind":"output","q":"变量插值：- 与 :- 的最终值","stem":"已知： .env 文件: TAG=1.4.2 LOG_LEVEL= 宿主 shell: LOG_LEVEL=debug compose: image: app:${TAG:-latest} environment: LOG_LEVEL: ${LOG_LEVEL:-info} 请写出（1）最终使用的镜像 image ；（2）容器内 LOG_LEVEL 的最终值。","opts":[],"ans":"image: app:1.4.2 容器内 LOG_LEVEL: debug","why":"考插值与优先级两条规则的叠加，属于「两个知识点一起考」的典型题。"},{"kind":"fix_error","q":"改错：慢启动服务被 healthcheck 反复杀掉的 compose 片段","stem":"下面这段 compose 用于部署一个需要跑数据库迁移的 Java 服务（冷启动约 40 秒）。上线后它永远起不来：每次启动到一半就被重启。请指出至少 3 处错误并给出正确写法。 yaml services: db: image: postgres:17.2-alpine api: image: registry.internal/app:1.4.2 depends_on: db: conditi…","opts":[],"ans":"db 缺 healthcheck；api 缺 start_period；timeout > interval；retries=1 太敏感","why":"综合考 healthcheck 五字段语义与 depends_on 条件的配合，是本章最实用的改错题。"},{"kind":"coding","q":"实现宿主端口冲突检测器","stem":"用 Python 3.13 标准库实现 detect_conflict(services)，检测 compose 中多个服务是否把同一个宿主端口发布出去。 输入：{服务名: {ports: [...]}}，ports 元素形如 80:80、5432、127.0.0.1:6379:6379。 要求： 1. 只写容器端口（5432，宿主端口随机）不构成冲突； 2. 宿主 IP + 宿主端口 + 协议三…","opts":[],"ans":"冲突数 = 2 0.0.0.0:80/tcp 被 web 与 api 同时声明 0.0.0.0:80/tcp 被 web 与 admin 同时声明","why":"把「端口发布 vs 暴露」变成可判定规则，对应 examples/ex10。"},{"kind":"output","q":"日志轮转容量与磁盘撑爆时间计算","stem":"某宿主上有 6 个容器，单容器日志速率 80 MiB/h，磁盘剩余空间 40 GiB（40960 MiB）。 （1）若配置 max-size: 20m、max-file: 5，这 6 个容器的日志占用上限是多少 MiB？ （2）若不配置轮转（默认 json-file 无限制），多少整数小时后磁盘被写满？ （只要求给出两个整数，1 GiB = 1024 MiB）","opts":[],"ans":"轮转后上限: 600 MiB 不轮转撑爆小时数: 85","why":"把「日志要不要配轮转」变成可算的数字，对应 examples/ex06。"},{"kind":"coding","q":"依赖图环检测与拓扑排序（有向图判环）","stem":"Compose 的 depends_on 构成一张有向图：服务是顶点，A depends_on B 表示一条 B → A 的边。可编排的充要条件是图中无环。 请用 Python 3.13 实现 topo_or_cycle(graph)： - 输入 graph: dict[str, list[str]]，键是服务名，值是它依赖的服务列表； - 若无环，返回 (True, 拓扑序列表)——用 Kahn…","opts":[],"ans":"用例1: (True, ['db', 'redis', 'api', 'web']) 用例2: (False, ['api', 'cache', 'web'])","why":"把 compose 依赖分析还原成 408 数据结构的有向图判环 + 拓扑排序，对应 examples/ex01。"},{"kind":"coding","q":"最小启动批次划分：把依赖图按层分组","stem":"编排器启动一组服务时，同一批次内的服务互不依赖、可以并行启动，批次数就是启动过程的关键路径长度（理论下界）。 请用 Python 3.13 实现 startup_batches(graph)： - 输入同上一题的 graph； - 无环时返回 (True, [[批次1服务...], [批次2服务...], ...])，每批内部按字典序； - 有环时返回 (False, [])。 再回答：若 red…","opts":[],"ans":"用例1: (True, [['db', 'redis'], ['api'], ['web']]) 用例2: (False, []) 批次划分不随耗时变化： True","why":"把拓扑排序升级为层次划分，并澄清「结构」与「耗时」两个维度，对应 examples/ex01。"}],"works":[{"h":"用短语法 depends_on 以为能保证依赖就绪","d":"现象：compose up 成功，但 api 日志第一行就是 connection refused，前端 500。根因：短语法等价于 condition: service_started，只等容器进程被创建，不等应用能接受连接；数据库此时还在 initdb 与跑迁移。正确做法：被依赖方配 healthcheck，依赖方写 depend…"},{"h":"写了 condition: service_healthy 却忘了给被依赖方配 health…","d":"现象：compose 报 dependency failed to start，或者干脆永远卡住。根因：没有 healthcheck 的服务永远不会进入 healthy 状态，条件无法满足。正确做法：健康检查要成对配置——db 有、api 依赖 db；api 自己也必须有，才能供 web 依赖。"},{"h":"依赖图里出现环","d":"现象：编排器无法确定启动顺序，或报 cycle detected。根因：A 依赖 B、B 又依赖 A，说明服务职责切错了。正确做法：抽第三个服务、或改成消息队列异步解耦；绝不能靠 restart: always 掩盖——那只会变成两个服务互相等待的崩溃循环。（ex01 实测：三节点环与自环均无法排出拓扑序）"},{"h":"健康检查不设 start_period 导致慢启动服务被反复杀","d":"现象：服务每次启动到一半就被重启，永远起不来。根因：migrations/大表预热期间探测必然失败，达到 retries 就被判 unhealthy，进而触发重启，形成「起一半被杀」的死循环。正确做法：设 start_period（如 30s~60s）覆盖初始化窗口；经验值 interval=10s timeout=3s retrie…"},{"h":"以为健康检查失败一次就 unhealthy","d":"现象：偶发抖动被误判为故障，触发不必要的重启与告警。根因：状态机要求连续失败 retries 次，中间任何一次成功都会把计数清零。正确做法：理解这是抗噪设计，需要灵敏度就调小 retries/interval，不要误以为机制失效。（ex03 实测：抖动序列 8 次探测从未 unhealthy）"},{"h":"在容器里用 localhost 访问同一 compose 的其他服务","d":"现象：connection refused 或 no such host，而宿主上明明能连。根因：每个容器有独立 net namespace，localhost 是各自的 loopback。正确做法：容器间一律用服务名作为 DNS 名（db:5432），并把服务放进同一个自定义网络。"},{"h":"用默认 bridge 网络而不是自定义网络","d":"现象：容器间用服务名解析失败（no such host）。根因：Docker 的内嵌 DNS（容器内的 127.0.0.11）只存在于自定义网络；默认 docker0 网桥没有它，--link 也已废弃。正确做法：显式声明 network 并把服务都加进去；compose 默认创建的 <project>_default 就够用。"},{"h":"以为 expose 会把端口发布到宿主","d":"现象：写了 expose: 8080，宿主 curl 连不上。根因：expose 只写进元数据，不做任何映射；ports 才在 iptables nat 表里加 DNAT。正确做法：需要宿主访问就写 ports，并记住宿主端口在前（8081:8080）。中间件（db/redis）出于安全应不发布。（ex10 实测：只写容器端口不构成冲…"}],"asks":[{"q":"depends_on 能保证依赖就绪吗？为什么 condition: service_healthy 才算数？","a":"不能。 - 短语法 depends_on: [db] 等价于 condition: service_started，只保证 db 的容器进程已被创建（PID 1 已 exec），不保证它能接受连接； - 「启动」是一个事件，「就绪」是一个谓词，两者之间隔着不可静态界定的初始化时间 T_init（initdb、跑迁移、预热缓存），可能 0.2 秒也可能 5 分钟； - condition: serv…","fu":["写了 service_healthy 但忘了给 db 配 healthcheck 会怎样？（条件永远无法满足，卡住或失败…","healthcheck 失败一次就 unhealthy 吗？（不，要连续失败 retries 次，中间成功即清零）"],"tag":"通用/字节"},{"q":"容器退出码 137 是什么意思？怎么排查和预防？","a":"含义：137 = 128 + 9，即进程被 SIGKILL 杀死。容器场景下最常见的原因是 OOMKilled——内存超过 cgroup 的 memory.max 硬上限，触发内核 OOM killer。 排查顺序： 1. docker inspect <id> 看 State.OOMKilled 字段是否为 true； 2. docker stats 看内存用量曲线（关注 P99 而不是平均值）…","fu":["CPU 超限会退出吗？（不会，被 CFS 节流，只是变慢）","为什么内存超限只能杀进程而不能让分配失败？（Linux 默认 overcommit，分配早已成功，物理页在缺页时才分配）"],"tag":"通用/阿里"},{"q":"Compose 环境变量的优先级是怎样的？.env 和 shell 谁优先？","a":"按 Docker 官方文档，从高到低五级： 1. CLI：docker compose run -e VAR=v / --env； 2. 插值：environment 或 env_file 的值来自 shell 或环境文件——其中 shell（宿主 OS 环境）优先于 .env； 3. environment 属性的显式值； 4. env_file 属性的显式值； 5. 镜像里的 ENV 指令（仅…","fu":[".env 里配了一堆值，容器里 env 看不到，为什么？（它只是插值来源，没配 environment/env_file…","${VAR:-x} 与 ${VAR-x} 有什么区别？（空串是否算已定义）"],"tag":"通用/字节"},{"q":"生产环境为什么不能用 latest 标签？digest 又是什么？","a":"latest 是浮动指针。它把「最新」这个时间相关的概念编码进了一个要求确定性的部署清单里： - 不可复现：同一份 compose 文件今天和明天 up 出来的可能是两个版本； - 不可回滚：出事后重新拉 app:latest，拿到的还是新版本，等于没回滚； - 不可审计：看清单无法知道线上跑的究竟是哪个构建产物。 digest 是内容的密码学哈希（内容寻址）。app@sha256:... 直接标…","fu":["tag 和 digest 的本质区别？（tag 是可变名字，digest 由内容唯一决定）","如果一定要用 tag，如何保证可回滚？（约定 tag 不可变，push 前校验 digest 是否已存在）"],"tag":"通用/腾讯"}]}];

